const NUM_ITEMS = ITEMS.length;

// Resolve drops table -> array of [itemKey, count] entries (+special handlers)
// 1:1 with BlockBehaviour.getDestroyProgress & hasCorrectToolForDrops
function resolveDrops(blockId, meta, toolDef, fortuneLvl) {
  const bl = BLOCKS[blockId];
  if (!bl || bl.hardness < 0) return [];
  if (!canHarvest(blockId, toolDef)) return [];
  if (bl.key.endsWith('_leaves') && toolDef && toolDef.type === 'shears') {
    return [[bl.key, 1]];
  }
  if ((bl.key === 'short_grass' || bl.key === 'fern') && toolDef && toolDef.type === 'shears') {
    return [[bl.key, 1]];
  }
  let d = bl.drops;
  if (d === null) return [];
  if (d === undefined || d === 'self') return [[bl.key, 1]];
  if (typeof d === 'string') {
    if (d === 'wheat_crop') {
      if (meta >= 7) return [['wheat_item', 1], ['wheat_seeds', 1 + fortuneLvl]];
      return [['wheat_seeds', 1]];
    }
    if (d === 'nether_wart_crop') return [['nether_wart', meta >= 3 ? randInt(2, 4) : 1]];
    return [[d, 1]];
  }
  const out = [];
  for (const [k, v] of Object.entries(d)) {
    if (k === 'self') { out.push([bl.key, v]); continue; }
    if (k === 'sapling5') { if (chance(0.05 + fortuneLvl * 0.0125)) out.push([`${bl.key.replace('_leaves', '_sapling')}`, 1]); continue; }
    if (k === 'apple1') { if (chance(0.005 + fortuneLvl * 0.0025)) out.push(['apple', 1]); continue; }
    if (k === 'wheat_crop') {
      if (meta >= 7) { out.push(['wheat_item', 1]); out.push(['wheat_seeds', randInt(0, 3) + fortuneLvl]); }
      else out.push(['wheat_seeds', 1]);
      continue;
    }
    if (k === 'nether_wart_crop') {
      out.push(['nether_wart', meta >= 3 ? randInt(2, 4) : 1]);
      continue;
    }
    if (typeof v === 'number') {
      if (k === 'flint') {
        const flintChance = fortuneLvl >= 3 ? 1.0 : (fortuneLvl === 2 ? 0.25 : (fortuneLvl === 1 ? 0.14 : 0.10));
        if (chance(flintChance)) out.push(['flint', 1]);
        else out.push(['gravel', 1]);
        continue;
      }
      if (k.startsWith('redstone') || k.startsWith('lapis') || k.startsWith('diamond') || k.startsWith('emerald') || k.startsWith('coal') || k.startsWith('quartz') || k.startsWith('raw_')) {
        let n = v;
        if (fortuneLvl > 0) n += randInt(0, fortuneLvl + 1);
        out.push([k, n]); continue;
      }
      out.push([k, v]);
    }
  }
  return out;
}

// 1:1 BlockBehaviour.hasCorrectToolForDrops check (from decompiled BlockBehaviour.java & ToolMaterial.java)
function canHarvest(blockId, toolDef) {
  const bl = BLOCKS[blockId];
  if (!bl) return false;
  if (bl.key === 'snow_layer' || bl.key === 'snow_block') {
    return !!(toolDef && toolDef.type === 'shovel');
  }
  if (bl.key === 'cobweb') {
    return !!(toolDef && (toolDef.type === 'sword' || toolDef.type === 'shears'));
  }
  if (bl.tool !== 'pickaxe') return true;
  if (!toolDef || toolDef.type !== 'pickaxe') return false;
  const reqTier = bl.minTier || 0;
  return toolDef.tier >= reqTier;
}

// ============================================================================
// Part 03a: Procedural texture atlas — original pixel art painted by code
// Every texture in this game is generated at runtime. No external assets.
// ============================================================================
const C = h => [parseInt(h.slice(1, 3), 16), parseInt(h.slice(3, 5), 16), parseInt(h.slice(5, 7), 16)];
const sh = (c, f) => [clamp(c[0] * f, 0, 255) | 0, clamp(c[1] * f, 0, 255) | 0, clamp(c[2] * f, 0, 255) | 0];
const mixc = (a, b, t) => [lerp(a[0], b[0], t) | 0, lerp(a[1], b[1], t) | 0, lerp(a[2], b[2], t) | 0];

const TILE_SIZE = 16;
const ATLAS_COLS = 32, ATLAS_ROWS = 32;
const TILE = new Map();
function regTile(name) { if (!TILE.has(name)) TILE.set(name, TILE.size); return TILE.get(name); }

function makePaintCtx(img, seed) {
  const d = img.data, rng = mulberry32(seed);
  const api = {
    rng, w: TILE_SIZE, h: TILE_SIZE,
    px(x, y, c, a = 255) {
      x |= 0; y |= 0;
      if (x < 0 || y < 0 || x > 15 || y > 15) return;
      const i = (y * 16 + x) * 4;
      d[i] = c[0]; d[i + 1] = c[1]; d[i + 2] = c[2]; d[i + 3] = a;
    },
    get(x, y) { const i = ((y & 15) * 16 + (x & 15)) * 4; return [d[i], d[i + 1], d[i + 2], d[i + 3]]; },
    rect(x, y, w, h, c, a = 255) { for (let yy = y; yy < y + h; yy++) for (let xx = x; xx < x + w; xx++) api.px(xx, yy, c, a); },
    fill(c, a = 255) { api.rect(0, 0, 16, 16, c, a); },
    clear() { api.rect(0, 0, 16, 16, [0, 0, 0], 0); },
    noise(c1, c2, p = 0.5) { for (let y = 0; y < 16; y++) for (let x = 0; x < 16; x++) api.px(x, y, rng() < p ? c1 : c2); },
    vary(base, amt = 0.12) { for (let y = 0; y < 16; y++) for (let x = 0; x < 16; x++) api.px(x, y, sh(base, 1 + (rng() - 0.5) * 2 * amt)); },
    specks(c, n, a = 255) { for (let i = 0; i < n; i++) api.px((rng() * 16) | 0, (rng() * 16) | 0, c, a); },
    borderShade(f1 = 1.18, f2 = 0.82) {
      for (let i = 0; i < 16; i++) {
        const t1 = api.get(i, 0), t2 = api.get(i, 15), l1 = api.get(0, i), l2 = api.get(15, i);
        api.px(i, 0, sh(t1, f1), t1[3]); api.px(i, 15, sh(t2, f2), t2[3]);
        const ll1 = api.get(0, i), ll2 = api.get(15, i);
        api.px(0, i, sh(ll1, f1), ll1[3]); api.px(15, i, sh(ll2, f2), ll2[3]);
      }
    },
    blobs(c, n, rMin, rMax, a = 255) {
      for (let i = 0; i < n; i++) {
        const cx = rng() * 16, cy = rng() * 16, r = rMin + rng() * (rMax - rMin);
        for (let y = Math.floor(cy - r); y <= cy + r; y++) for (let x = Math.floor(cx - r); x <= cx + r; x++) {
          const dx = x + .5 - cx, dy = y + .5 - cy;
          if (dx * dx + dy * dy <= r * r + (rng() - .5)) api.px(x, y, sh(c, 1 + (rng() - .5) * .25), a);
        }
      }
    },
    hline(y, c, x0 = 0, x1 = 15) { for (let x = x0; x <= x1; x++) api.px(x, y, c); },
    vline(x, y0, y1, c) { for (let y = y0; y <= y1; y++) api.px(x, y, c); },
  };
  return api;
}

