const TILE_PAINTERS = {};
const TP = (n, fn) => { regTile(n); TILE_PAINTERS[n] = fn; };

// ---------- Stone family ----------
TP('stone', t => { t.vary(PAL.stone, .1); t.specks(sh(PAL.stone, .85), 22); t.specks(sh(PAL.stone, 1.1), 14); });
