TP('farmland', t => { t.vary(sh(PAL.dirt, .8), .12); for (let y = 1; y < 16; y += 4) t.hline(y, sh(PAL.dirt, .55)); t.specks(sh(PAL.dirt, .6), 8); });
TP('farmland_moist', t => { t.vary(sh(PAL.dirt, .55), .1); for (let y = 1; y < 16; y += 4) t.hline(y, sh(PAL.dirt, .35)); });
