TP('cut_sandstone', t => { t.vary(C('#d8cf9e'), .04); t.hline(7, C('#bfb37c')); t.hline(15, C('#bfb37c')); t.hline(0, C('#e5ddae')); t.hline(8, C('#e5ddae')); });
TP('red_sandstone', t => { t.vary(C('#bd6c3a'), .06); for (let y = 4; y < 16; y += 4) t.hline(y, C('#a85c2e')); });

