TP('snow_block', t => { t.vary(PAL.snow, .03); });
TP('ice', t => { t.vary(C('#7daaf0'), .06, ); for (let i = 0; i < 4; i++) { const x = (t.rng() * 12) | 0, y = (t.rng() * 12) | 0; t.rect(x, y, 3, 1, C('#a9c8f5')); } t.borderShade(1.1, .9); });
