function bucketPaint(t, liquid) {
  t.clear();
  t.rect(4, 4, 8, 9, C('#a8a8a8'));
  t.rect(3, 5, 10, 8, C('#c8c8c8'));
  t.rect(5, 6, 6, 2, liquid || C('#8a8a8a'));
  t.rect(3, 13, 10, 1, C('#8a8a8a'));
}
