        const [sky, blk] = lightAt(x, y, z);
        this.boxMesh(mesh, x, y, z, 4 / 16, 0, 6 / 16, 12 / 16, 3 / 16, 10 / 16, tBase, sky, blk, [1, 1, 1, 1]);
