class Entity {
  constructor(type, x, y, z, def, opts = {}) {
    this.type = type;
    this.def = def;
    this.x = x; this.y = y; this.z = z;
    this.vx = 0; this.vy = 0; this.vz = 0;
    this.rx = x; this.ry = y; this.rz = z;
    this.yaw = rand() * Math.PI * 2; this.pitch = 0;
    this.w = def.w || .5; this.h = def.h || .5;
    this.health = def.health || 1;
    this.maxHealth = this.health;
    this.dead = false; this.deathTime = 0; this.hurtTime = 0;
    this.hittable = true;
    this.renderParts = true; // every entity renders (items via drawItem, mobs via drawBoxes)
    this.onGround = false;
    this.age = 0;
    this.gravity = !!def.gravity;
    this.hostile = !!def.hostile;
    this.itemEntity = type === 'item';
    this.xpEntity = type === 'xp';
    this.walkAnim = 0; this.walkSpeed = 0;
    this.attackCD = 0;
    this.fuse = -1;
    this.inLove = 0; this.babyAge = 0;
    this.soundCD = randInt(40, 200);
    this.ai = { wanderT: 0, wx: 0, wz: 0, target: null, panicT: 0 };
    Object.assign(this, opts);
    if (def.dragon) { this.orbit = 0; this.orbitR = 38; this.orbitY = 80; }
  }

  collides(px, py, pz) {
    const hw = this.w / 2;
    const x0 = Math.floor(px - hw), x1 = Math.floor(px + hw);
    const y0 = Math.floor(py), y1 = Math.floor(py + this.h - 0.001);
    const z0 = Math.floor(pz - hw), z1 = Math.floor(pz + hw);
    for (let y = y0; y <= y1; y++) for (let z = z0; z <= z1; z++) for (let x = x0; x <= x1; x++) {
      const id = G.world.getBlock(x, y, z);
      if (id < 0) return true;
      if (id > 0 && BLOCKS[id].solid) return true;
    }
    return false;
  }

  move(dx, dy, dz) {
    const steps = Math.ceil(Math.max(Math.abs(dx), Math.abs(dy), Math.abs(dz)) * 3);
    if (steps <= 0) return;
    const sx = dx / steps, sy = dy / steps, sz = dz / steps;
    let hitX = false, hitY = false, hitZ = false;
    for (let i = 0; i < steps; i++) {
      if (sx !== 0) { if (!this.collides(this.x + sx, this.y, this.z)) this.x += sx; else hitX = true; }
      if (sy !== 0) { if (!this.collides(this.x, this.y + sy, this.z)) this.y += sy; else { hitY = true; if (sy < 0) this.onGround = true; } }
      if (sz !== 0) { if (!this.collides(this.x, this.y, this.z + sz)) this.z += sz; else hitZ = true; }
    }
    return { hitX, hitY, hitZ };
  }

  setVelocityFromKnockback(kx, kz, strength) {
    this.vx += kx * strength; this.vz += kz * strength; this.vy = Math.max(this.vy, 0.36);
  }

  damage(amount, attacker, cause) {
    if (this.dead || this.type === 'item' || this.type === 'xp') return;
    this.health -= amount;
    this.hurtTime = 10;
    SFX.playHit();
    if (attacker && (attacker.isPlayer || attacker === G.player)) {
      const dx = this.x - attacker.x, dz = this.z - attacker.z;
      const l = Math.hypot(dx, dz) || 1;
      this.setVelocityFromKnockback(dx / l, dz / l, .35);
      this.ai.target = attacker;
      this.ai.panicT = 100;
      // sprint knockback
      if (attacker.sprinting) { this.vx += dx / l * .5; this.vz += dz / l * .5; }
    }
    if (this.health <= 0) this.die(attacker);
  }

  die(attacker) {
    this.dead = true;
    this.deathTime = 0;
    const d = this.def;
    if (d.drops) {
      for (const [key, mn, mx] of d.drops) {
        const n = randInt(mn, mx);
        if (n > 0) dropItem(this.x, this.y + .5, this.z, key, n);
      }
    }
    if (this.type === 'item' || this.type === 'xp') return;
    if (d.xp) spawnXPOrbs(this.x, this.y + .5, this.z, d.xp);
    if (attacker === G.player) {
      G.stats.kills++;
      Advancements.onKill(!!d.hostile);
    }
    if (d.dragon) {
      spawnXPOrbs(this.x, this.y + 1, this.z, 120);
      WinDragonFight();
    }
    if (d.wither) {
      spawnXPOrbs(this.x, this.y + 1, this.z, 100);
      dropItem(this.x, this.y + 1, this.z, 'glass_bottle', 1);
      UI.updateBossBar(null);
      Chat.add('§dThe Wither has been slain!');
    }
  }

  tick() {
    this.age++;
    // remote players are driven entirely by snapshot interpolation (Net.tick)
    if (this.noAI) { this.px = this.x; this.py = this.y; this.pz = this.z; return; }
    this.yawO = this.yaw; // kept for the render-alpha yaw interpolation
    if (this.attackCD > 0) this.attackCD--; // unified cooldown (MC: 20 ticks = 1 s between melee hits)
    if (this.hurtTime > 0) this.hurtTime--;
    if (this.dead) { this.deathTime++; return; }
    // Villager.java restock(): offers reset 2× per day (morning + afternoon)
    if (this.type === 'villager') villagerRestock(this);
    switch (this.type) {
      case 'item': this.tickItem(); return;
      case 'xp': this.tickXP(); return;
      case 'arrow': this.tickArrow(); return;
      case 'snowball': case 'egg': case 'pearl': case 'xp_bottle': this.tickThrowable(); return;
      case 'fireball': this.tickFireball(); return;
      case 'wither_skull_proj': this.tickWitherSkull(); return;
      case 'tnt': this.tickTNT(); return;
      case 'falling': this.tickFalling(); return;
      case 'boat_ent': this.tickBoat(); return;
      case 'cart_ent': this.tickCart(); return;
      default: this.tickMob(); return;
    }
  }

  tickWitherSkull() {
    this.vy -= 0.01;
    const id = G.world.getBlock(Math.floor(this.x + this.vx * DT * 3), Math.floor(this.y + this.vy * DT * 3), Math.floor(this.z + this.vz * DT * 3));
    const p = G.player;
    let hit = (id > 0 && BLOCKS[id].solid);
    if (!hit && p && !p.dead) {
      if (Math.hypot(p.x - this.x, p.y + 1 - this.y, p.z - this.z) < 1.3) hit = true;
    }
    if (hit) { explode(this.x, this.y, this.z, 1.6); this.dead = true; return; }
    this.x += this.vx * DT; this.y += this.vy * DT; this.z += this.vz * DT;
    if (this.age > 300) this.dead = true;
  }

  controls(ix, iz, jump) {
    if (this.type === 'boat_ent') {
      if (ix) this.yaw += ix * 0.08;
      const th = iz * 0.055;
      this.vx += -Math.sin(this.yaw) * th;
      this.vz += -Math.cos(this.yaw) * th;
    } else if (this.type === 'cart_ent') {
      const bx = Math.floor(this.x), by = Math.round(this.y - 0.1), bz = Math.floor(this.z);
      const onRail = G.world.getBlock(bx, by, bz) === B.rail;
      if (onRail) {
        this.railAxis = this.railAxis || ((G.world.getBlock(bx + 1, by, bz) === B.rail || G.world.getBlock(bx - 1, by, bz) === B.rail) ? 'x' : 'z');
        if (iz) this.railVel = (this.railVel || 0) + iz * 0.02;
        this.railVel = clamp((this.railVel || 0) * 0.98, -0.5, 0.5);
        if (this.railAxis === 'x') { this.vx = this.railVel; this.vz = 0; }
        else { this.vz = this.railVel; this.vx = 0; }
      } else {
        this.vx *= 0.9; this.vz *= 0.9;
      }
    }
  }

  tickBoat() {
    const inWater = G.world.getBlock(Math.floor(this.x), Math.floor(this.y + 0.1), Math.floor(this.z)) === B.water;
    if (inWater) { this.vy = Math.max(this.vy - 0.02, -0.05); this.y += (63.9 - this.y) * 0.08; }
    else this.vy -= 0.04;
    this.vx *= 0.92; this.vz *= 0.92;
    this.move(this.vx * 20 * DT, this.vy, this.vz * 20 * DT);
    if (this.y < -20) this.dead = true;
  }

  tickCart() {
    const bx = Math.floor(this.x), by = Math.round(this.y - 0.1), bz = Math.floor(this.z);
    const onRail = G.world.getBlock(bx, by, bz) === B.rail;
    if (onRail) {
      if (this.railAxis === 'x') { this.z = bz + 0.5; this.vz = 0; }
      else if (this.railAxis === 'z') { this.x = bx + 0.5; this.vx = 0; }
      this.y = by + 0.06;
      this.move(this.vx, 0, this.vz);
      const aheadX = Math.floor(this.x + Math.sign(this.vx) * 0.6), aheadZ = Math.floor(this.z + Math.sign(this.vz) * 0.6);
      const ahead = this.railAxis === 'x' ? G.world.getBlock(aheadX, by, bz) : G.world.getBlock(bx, by, aheadZ);
      if (ahead !== B.rail) {
        if (G.world.getBlock(bx, by, bz + 1) === B.rail || G.world.getBlock(bx, by, bz - 1) === B.rail) { this.railAxis = 'z'; this.vx = 0; }
        else if (G.world.getBlock(bx + 1, by, bz) === B.rail || G.world.getBlock(bx - 1, by, bz) === B.rail) { this.railAxis = 'x'; this.vz = 0; }
        else { this.vx = 0; this.vz = 0; }
      }
    } else {
      this.vy -= 0.04;
      this.move(this.vx, this.vy, this.vz);
      if (this.onGround) { this.vy = 0; this.vx *= 0.9; this.vz *= 0.9; }
    }
    if (this.y < -20) this.dead = true;
  }

  tickItem() {
    // item physics in TICK units (velocities are blocks/tick, like the player):
    // gravity 0.08, air drag 0.98 — items land fast and snappy
    this.vy -= 0.08;
    this.vy *= 0.98;
    this.vx *= 0.98;
    this.vz *= 0.98;
    const inW = G.world.getBlock(Math.floor(this.x), Math.floor(this.y + .3), Math.floor(this.z)) === B.water;
    if (inW) { this.vy = Math.min(this.vy + 0.04, 0.1); this.fallDistance = 0; }
    this.vx *= .9; this.vz *= .9;
    this.onGround = false;
    this.move(this.vx, this.vy, this.vz);
    if (this.onGround) this.vy = 0;
    // merge
    if (this.age % 10 === 0) {
      for (const o of G.entities) {
        if (o !== this && !o.dead && o.type === 'item' && o.itemStack && this.itemStack &&
          o.itemStack.id === this.itemStack.id && !o.itemStack.ench && !this.itemStack.ench &&
          Math.hypot(o.x - this.x, o.y - this.y, o.z - this.z) < 1.5 &&
          this.itemStack.count + o.itemStack.count <= ITEMS[this.itemStack.id].stack) {
          this.itemStack.count += o.itemStack.count;
          o.dead = true;
        }
      }
    }
    if (this.age > 6000) { this.dead = true; return; }
    // aggressive magnet + pickup: a sprinting player must collect a drop the
    // moment he passes over it — no trailing behind
    const p = G.player;
    if (p && !p.dead && this.age > 2) {
      const dx = p.x - this.x, dy = (p.y + .8) - this.y, dz = p.z - this.z;
      const dh = Math.hypot(dx, dz);
      // MC-AABB-style pickup: whenever the player is standing OVER the drop
      // (horizontal contact), it is collected instantly — a spherical check
      // against the body center alone misses it because of the height offset
      if (dh < 0.8 && Math.abs(dy) < 1.3) {
        const left = p.addItem(this.itemStack.id, this.itemStack.count, this.itemStack.dur, this.itemStack.ench);
        if (left === 0) { this.dead = true; SFX.playPop(); return; }
        else this.itemStack.count = left;
      }
      const d = Math.hypot(dx, dy, dz) || .001;
      if (d < 3.5) {
        // strong pull that outruns the friction (0.9 drag per tick)
        this.vx += dx / d * .22; this.vy += dy / d * .22; this.vz += dz / d * .22;
      }
      if (d < 1.1) {
        // final snap: fly straight at the player at up to 0.6 blocks/tick
        const sp = Math.min(.6, d * .3 + .15);
        this.vx = dx / d * sp; this.vy = dy / d * sp; this.vz = dz / d * sp;
      }
      if (d < 0.7) {
        const left = p.addItem(this.itemStack.id, this.itemStack.count, this.itemStack.dur, this.itemStack.ench);
        if (left === 0) { this.dead = true; SFX.playPop(); return; }
        else this.itemStack.count = left;
      }
    }
  }

  tickXP() {
    this.physics(.04);
    this.vx *= .9; this.vz *= .9;
    if (this.age > 6000) { this.dead = true; return; }
    const p = G.player;
    if (p && !p.dead) {
      const dx = p.x - this.x, dy = (p.y + .8) - this.y, dz = p.z - this.z;
      const d = Math.hypot(dx, dy, dz);
      if (d < 4) { this.vx += dx / d * .14; this.vy += dy / d * .14; this.vz += dz / d * .14; }
      if (d < 0.8) { p.addXP(this.value); this.dead = true; SFX.playXPOrb(); }
    }
  }

  tickArrow() {
    if (this.inGround) {
      this.age++;
      const p = G.player;
      if (p && !p.dead && this.age > 20 && Math.hypot(p.x - this.x, p.y + 1 - this.y, p.z - this.z) < 1.2) {
        if (p.addItem(I.arrow, 1) === 0) { this.dead = true; SFX.playPop(); }
      }
      if (this.age > 1200) this.dead = true;
      return;
    }
    this.vy -= .05;
    this.vx *= .99; this.vz *= .99; this.vy *= .99;
    const speed = Math.hypot(this.vx, this.vy, this.vz);
    if (speed < 0.1) { this.inGround = true; return; }
    // sample along path
    const steps = Math.ceil(speed * 2);
    for (let i = 0; i < steps; i++) {
      this.x += this.vx / steps; this.y += this.vy / steps; this.z += this.vz / steps;
      const id = G.world.getBlock(Math.floor(this.x), Math.floor(this.y), Math.floor(this.z));
      if (id > 0 && BLOCKS[id].solid) { this.inGround = true; this.vx = this.vy = this.vz = 0; SFX.playDig('stone'); return; }
      // entity hit
      for (const e of G.entities) {
        if (e === this || e.dead || !e.hittable || e.type === 'item' || e.type === 'xp' || e.type === 'arrow') continue;
        if (this.owner === e) continue;
        const hw = e.w / 2;
        if (this.x > e.x - hw && this.x < e.x + hw && this.y > e.y && this.y < e.y + e.h && this.z > e.z - hw && this.z < e.z + hw) {
          const dmg = Math.max(1, Math.round(speed * 1.2));
          e.damage(dmg, this.owner);
          this.dead = true;
          return;
        }
      }
      // player hit
      const p = G.player;
      if (p && !p.dead && this.owner !== p && this.x > p.x - .4 && this.x < p.x + .4 && this.y > p.y && this.y < p.y + 1.9 && this.z > p.z - .4 && this.z < p.z + .4) {
        const ad = mobDmg(Math.max(1, Math.round(speed)));
        if (ad > 0) p.damage(ad, 'arrow:' + this.type);
        this.dead = true;
        return;
      }
    }
  }

  tickThrowable() {
    this.vy -= .05;
    const id = G.world.getBlock(Math.floor(this.x + this.vx * .1), Math.floor(this.y + this.vy * .1), Math.floor(this.z + this.vz * .1));
    let hitEnt = null;
    for (const e of G.entities) {
      if (e === this || e.dead || !e.hittable || e.type === 'item' || e.type === 'xp') continue;
      const hw = e.w / 2;
      if (this.x > e.x - hw - .2 && this.x < e.x + hw + .2 && this.y > e.y - .2 && this.y < e.y + e.h + .2 && this.z > e.z - hw - .2 && this.z < e.z + hw + .2) { hitEnt = e; break; }
    }
    if (id > 0 && BLOCKS[id].solid || hitEnt) {
      if (this.type === 'snowball') { spawnParticles(this.x, this.y, this.z, 8, [.9, .95, 1]); }
      else if (this.type === 'egg') {
        spawnParticles(this.x, this.y, this.z, 6, [.9, .85, .7]);
        if (chance(.2)) spawnEntity('chicken', this.x, this.y, this.z);
      } else if (this.type === 'pearl') {
        const owner = this.owner;
        if (owner === G.player) {
          TeleportPlayer(this.x, this.y + .5, this.z);
          G.player.damage(5, 'pearl');
        }
      } else if (this.type === 'xp_bottle') {
        spawnParticles(this.x, this.y, this.z, 12, [0.35, 0.75, 1.0], true);
        SFX.playBreak('glass');
        spawnXPOrbs(this.x, this.y + 0.2, this.z, randInt(3, 11));
      }
      if (hitEnt && this.type === 'snowball') hitEnt.damage(1, this.owner);
      this.dead = true;
      return;
    }
    this.x += this.vx * DT; this.y += this.vy * DT; this.z += this.vz * DT;
    this.yaw = Math.atan2(this.vx, this.vz);
    if (this.age > 600) this.dead = true;
  }

  tickFireball() {
    this.vy -= .01;
    const id = G.world.getBlock(Math.floor(this.x + this.vx * DT), Math.floor(this.y + this.vy * DT), Math.floor(this.z + this.vz * DT));
    const p = G.player;
    let hitP = false;
    if (p && !p.dead) {
      const d = Math.hypot(p.x - this.x, p.y + 1 - this.y, p.z - this.z);
      if (d < 1.2) hitP = true;
    }
    if (id > 0 && BLOCKS[id].solid || hitP) {
      explode(this.x, this.y, this.z, 1.8);
      this.dead = true;
      return;
    }
    this.x += this.vx * DT; this.y += this.vy * DT; this.z += this.vz * DT;
    if (G.settings.particles && this.age % 2 === 0) spawnSmoke(this.x, this.y, this.z, 1, .5);
    if (this.age > 1200) this.dead = true;
  }

  tickTNT() {
    this.physics(.04);
    this.fuse--;
    if (G.settings.particles && this.age % 3 === 0) spawnSmoke(this.x, this.y + 1, this.z, 1);
    if (this.fuse <= 0) {
      this.dead = true;
      explode(this.x, this.y + .5, this.z, 4.2);
    }
  }

  tickFalling() {
    this.vy -= .04;
    const hit = this.move(0, this.vy * DT * 20 * DT * 0 + this.vy, 0);
    // use direct velocity integration per tick
    this.x += this.vx * DT; this.z += this.vz * DT;
    const below = G.world.getBlock(Math.floor(this.x), Math.floor(this.y - .05), Math.floor(this.z));
    if (this.onGround || (below > 0 && BLOCKS[below].solid)) {
      this.dead = true;
      const bx = Math.floor(this.x), by = Math.round(this.y), bz = Math.floor(this.z);
      G.world.setBlock(bx, by, bz, this.blockId, 0);
      SFX.playPlace('sand');
    } else if (this.y < -20) this.dead = true;
  }

  physics(gravity = .08) {
    if (this.def.flies) { this.vy *= .95; return; }
    this.vy -= gravity;
    this.vy *= 0.98;
    if (this.vy < -3.5) this.vy = -3.5;
    const inWater = G.world.getBlock(Math.floor(this.x), Math.floor(this.y + .3), Math.floor(this.z)) === B.water;
    if (inWater) { this.vy = Math.min(this.vy + .08, .2); }
    this.onGround = false;
    const hit = this.move(this.vx, this.vy, this.vz) || {};
    if (this.onGround) this.vy = 0;
    // Automatic 1-block obstacle jump for all walking mobs when blocked horizontally
    if ((hit.hitX || hit.hitZ) && this.onGround && !inWater) {
      this.vy = 0.42;
      this.onGround = false;
    }
  }

  tickMob() {
    const d = this.def;
    const p = G.player;
    // ambient sounds
    if (d.sound && --this.soundCD <= 0) {
      this.soundCD = randInt(150, 500);
      const dist = p ? Math.hypot(p.x - this.x, p.y - this.y, p.z - this.z) : 999;
      if (dist < 18) SFX.playMobSound(d.sound);
    }
    // burning in daylight
    if (d.burnsInDay && G.dimension === 0) {
      const sky = G.world.skyLight(Math.floor(this.x), Math.floor(this.y + d.h * .8), Math.floor(this.z));
      const day = isDaytime();
      if (sky >= 14 && day) {
        this.burnTime = (this.burnTime || 0) + 1;
        if (G.settings.particles && this.burnTime % 4 === 0) spawnFlame(this.x, this.y + rand() * d.h, this.z);
        if (this.burnTime % 20 === 0) this.damage(1);
      }
    }
    // breeding hearts
    if (this.inLove > 0) {
      this.inLove--;
      if (this.age % 10 === 0) spawnHeartParticles(this.x, this.y + this.h, this.z);
      // find partner
      for (const o of G.entities) {
        if (o !== this && !o.dead && o.type === this.type && o.inLove > 0 && Math.hypot(o.x - this.x, o.z - this.z) < 2.5) {
          this.inLove = 0; o.inLove = 0;
          const baby = spawnEntity(this.type, this.x, this.y, this.z);
          baby.babyAge = -1200; // 60s baby
          spawnHeartParticles(this.x, this.y + 1, this.z);
          spawnXPOrbs(this.x, this.y + .5, this.z, randInt(1, 7));
          break;
        }
      }
    }
    if (this.babyAge < 0) this.babyAge++;
    // egg laying
    if (d.laysEggs && this.age % 6000 === 0 && chance(.5)) dropItem(this.x, this.y + .3, this.z, 'egg', 1);

    const distP = p ? Math.hypot(p.x - this.x, p.y - this.y, p.z - this.z) : 999;

    // ---------- AI ----------
    let moveX = 0, moveZ = 0, speed = d.speed || .1;
    let wantJump = false;

    if (d.dragon) { this.tickDragon(p); this.physics(0); return; }
    if (d.wither) { this.tickWither(p); return; }

    if (d.hostile && p && !p.dead && G.gameMode !== 'creative' && G.gameMode !== 'spectator' && distP < (d.ranged ? 18 : 16)) {
      // chase
      const dx = p.x - this.x, dz = p.z - this.z;
      const l = Math.hypot(dx, dz) || 1;
      this.yaw = Math.atan2(dx, dz);
      if (d.neutralInLight && isDaytime() && G.world.skyLight(Math.floor(this.x), Math.floor(this.y + 1), Math.floor(this.z)) > 12 && !this.angerTime) {
        // passive in daylight
        [moveX, moveZ] = this.wander();
      } else if (d.ranged) {
        // skeleton keeps distance & shoots
        if (distP < 6) { moveX = -dx / l; moveZ = -dz / l; }
        else if (distP > 10) { moveX = dx / l; moveZ = dz / l; }
        else { moveX = -dz / l * .4; moveZ = dx / l * .4; }
        if (this.attackCD <= 0 && distP < 15) {
          this.attackCD = 40;
          const arrow = spawnEntity('arrow', this.x, this.y + this.h * .8, this.z, { owner: this });
          const tx = p.x + p.vx * 8 - this.x, ty = (p.y + 1.2) - (this.y + this.h * .8), tz = p.z + p.vz * 8 - this.z;
          const tl = Math.hypot(tx, ty, tz) || 1;
          const inacc = .08;
          arrow.vx = tx / tl * 22 * (1 + (rand() - .5) * inacc);
          arrow.vy = ty / tl * 22 + 2 * (1 + (rand() - .5) * inacc);
          arrow.vz = tz / tl * 22 * (1 + (rand() - .5) * inacc);
          SFX.playBowShoot();
        }
      } else if (d.creeper) {
        if (distP > 2.2) { moveX = dx / l; moveZ = dz / l; }
        if (distP < 3) {
          if (this.fuse < 0) { this.fuse = 30; SFX.playFuse(); }
        } else if (distP > 6 && this.fuse >= 0) this.fuse = -1;
        if (this.fuse >= 0) {
          this.fuse--;
          speed = 0;
          if (this.fuse <= 0) {
            this.dead = true;
            explode(this.x, this.y + .5, this.z, 3.2);
            return;
          }
        }
      } else if (d.shootsFireball) {
        // ghast
        this.hoverY = this.hoverY === undefined ? this.y : this.hoverY;
        if (distP < 24) {
          if (this.attackCD <= 0) {
            this.attackCD = 80;
            const fb = spawnEntity('fireball', this.x, this.y + this.h / 2, this.z, { owner: this });
            const tx = p.x - fb.x, ty = (p.y + 1) - fb.y, tz = p.z - fb.z;
            const tl = Math.hypot(tx, ty, tz) || 1;
            fb.vx = tx / tl * 9; fb.vy = ty / tl * 9; fb.vz = tz / tl * 9;
            SFX.playMobSound('ghast');
          }
          const l2 = Math.hypot(dx, dz) || 1;
          if (distP > 20) { moveX = dx / l2; moveZ = dz / l2; }
          else if (distP < 10) { moveX = -dx / l2; moveZ = -dz / l2; }
        }
        this.vy += ((this.hoverY - this.y) * .02 + Math.sin(this.age * .05) * .01);
        this.vx = lerp(this.vx, moveX * speed, .05);
        this.vz = lerp(this.vz, moveZ * speed, .05);
        this.yaw = Math.atan2(this.vx, this.vz);
        this.move(this.vx * DT, this.vy * DT, this.vz * DT);
        return;
      } else {
        moveX = dx / l; moveZ = dz / l;
        // melee attack
        if (distP < 1.8 && this.attackCD <= 0) {
          this.attackCD = 20;
          const md = mobDmg(d.damage || 2);
          if (md > 0) p.damage(md, 'mob:' + this.type);
          const kb = .3;
          p.vx += dx / l * kb * 4; p.vz += dz / l * kb * 4; p.vy = Math.max(p.vy, .3);
        }
      }
      wantJump = true;
    } else if (this.angerTime > 0 && p) {
      this.angerTime--;
      const dx = p.x - this.x, dz = p.z - this.z;
      const l = Math.hypot(dx, dz) || 1;
      moveX = dx / l; moveZ = dz / l; wantJump = true;
      if (distP < 1.8 && this.attackCD <= 0) { this.attackCD = 20; const md = mobDmg(d.damage || 2); if (md > 0) p.damage(md, 'mob:' + this.type); }
    } else if (d.passive) {
      // panic when hurt
      if (this.ai.panicT > 0) {
        this.ai.panicT--;
        speed *= 1.8;
        moveX = this.ai.wx; moveZ = this.ai.wz;
      }
      // follow player holding breeding food
      else if (p && !p.dead) {
        const held = p.getHeldItem();
        if (held && ITEMS[held.id].key === d.breedItem && distP < 8) {
          const dx = p.x - this.x, dz = p.z - this.z;
          const l = Math.hypot(dx, dz) || 1;
          if (distP > 1.8) { moveX = dx / l; moveZ = dz / l; }
        } else [moveX, moveZ] = this.wander();
      } else [moveX, moveZ] = this.wander();
    } else {
      [moveX, moveZ] = this.wander();
    }

    // Smooth yaw turn toward movement direction + movement integration (per-tick units)
    if (Math.hypot(moveX, moveZ) > 0.01) {
      const targetYaw = Math.atan2(moveX, moveZ);
      let diff = targetYaw - this.yaw;
      while (diff > Math.PI) diff -= Math.PI * 2;
      while (diff < -Math.PI) diff += Math.PI * 2;
      this.yaw += diff * 0.28;
    }
    this.vx = lerp(this.vx, moveX * speed, .25);
    this.vz = lerp(this.vz, moveZ * speed, .25);
    this.walkSpeed = Math.hypot(this.vx, this.vz);
    // previous values kept so drawBoxes can interpolate the leg swing with the
    // render alpha — without this the legs jump in visible 20 Hz steps
    this.walkAnimO = this.walkAnim;
    this.walkSpeedO = this.walkSpeed;
    this.walkAnim += this.walkSpeed * 3.2;

    // jump if blocked horizontally (both passive and hostile mobs jump 1-block steps)
    if (this.onGround && this.walkSpeed > .015) {
      const aheadX = Math.floor(this.x + moveX * (this.w * 0.5 + 0.35));
      const aheadZ = Math.floor(this.z + moveZ * (this.w * 0.5 + 0.35));
      const ahead = G.world.getBlock(aheadX, Math.floor(this.y + .1), aheadZ);
      const aheadUp = G.world.getBlock(aheadX, Math.floor(this.y + 1.1), aheadZ);
      if (ahead > 0 && BLOCKS[ahead].solid && !(aheadUp > 0 && BLOCKS[aheadUp].solid)) this.vy = .42;
    }
    // avoid walking into water/lava/deep cliffs (passives)
    if (d.passive && this.onGround && this.walkSpeed > .015) {
      const ax = Math.floor(this.x + Math.sign(moveX) * .8), az = Math.floor(this.z + Math.sign(moveZ) * .8);
      const below1 = G.world.getBlock(ax, Math.floor(this.y - 1), az);
      const below2 = G.world.getBlock(ax, Math.floor(this.y - 2), az);
      const at = G.world.getBlock(ax, Math.floor(this.y), az);
      if ((below1 === 0 && below2 === 0) || at === B.water || at === B.lava) {
        this.vx = 0; this.vz = 0;
        this.ai.wx = -this.ai.wx; this.ai.wz = -this.ai.wz;
      }
    }
    // water float
    const inWater = G.world.getBlock(Math.floor(this.x), Math.floor(this.y + .3), Math.floor(this.z)) === B.water;
    if (d.flies) {
      this.vy = lerp(this.vy, Math.sin(this.age * .04) * .05, .1);
      this.move(this.vx, this.vy, this.vz);
    } else if (inWater) {
      this.vy = Math.min(this.vy + .06, .14);
      this.move(this.vx * .6, this.vy, this.vz * .6);
    } else {
      if (d.slowFall && this.vy < -.12) this.vy = -.12;
      this.physics(.08);
    }
    if (this.y < -30) this.dead = true;
  }

  tickWither(p) {
    // fly toward the player, keep 8 blocks distance, shoot skulls
    const dx = p ? p.x - this.x : 0, dy = p ? (p.y + 1) - this.y : 0, dz = p ? p.z - this.z : 0;
    const l = Math.hypot(dx, dy, dz) || 1;
    const dir = l > 8 ? 1 : -0.5;
    this.vx = lerp(this.vx, (dx / l) * 0.18 * dir, 0.05);
    this.vy = lerp(this.vy, (dy / l) * 0.18 * dir + Math.sin(this.age * 0.05) * 0.01, 0.05);
    this.vz = lerp(this.vz, (dz / l) * 0.18 * dir, 0.05);
    this.yaw = Math.atan2(dx, dz);
    this.move(this.vx, this.vy, this.vz);
    if (p && this.attackCD <= 0 && !p.dead) {
      this.attackCD = 55;
      const sk = spawnEntity('wither_skull_proj', this.x, this.y + 2.6, this.z, { owner: this });
      const tx = p.x + p.vx * 10 - sk.x, ty = (p.y + 1.2) - sk.y, tz = p.z + p.vz * 10 - sk.z;
      const tl = Math.hypot(tx, ty, tz) || 1;
      sk.vx = tx / tl * 14; sk.vy = ty / tl * 14; sk.vz = tz / tl * 14;
      SFX.playMobSound('zombie');
    }
    if (G.settings.particles && this.age % 6 === 0) spawnSmoke(this.x, this.y + 2, this.z, 2, 0.1);
    UI.updateBossBar('Wither', this.health / this.maxHealth);
  }

  wander() {
    this.ai.wanderT--;
    if (this.ai.wanderT <= 0) {
      this.ai.wanderT = randInt(40, 160);
      if (chance(.55)) { this.ai.wx = 0; this.ai.wz = 0; }
      else {
        const a = rand() * Math.PI * 2;
        this.ai.wx = Math.sin(a); this.ai.wz = Math.cos(a);
      }
    }
    if (this.ai.wx || this.ai.wz) this.yaw = Math.atan2(this.ai.wx, this.ai.wz);
    return [this.ai.wx, this.ai.wz];
  }

  tickDragon(p) {
    this.orbit += .008;
    const tx = Math.cos(this.orbit) * this.orbitR, tz = Math.sin(this.orbit) * this.orbitR;
    const ty = this.orbitY + Math.sin(this.orbit * 3) * 6;
    if (p && !p.dead && chance(.006)) {
      // swoop at player
      this.swoopTarget = [p.x, p.y + 2, p.z];
      this.swoopT = 60;
    }
    let gx = tx, gy = ty, gz = tz;
    if (this.swoopT > 0) {
      this.swoopT--;
      if (this.swoopTarget) { gx = this.swoopTarget[0]; gy = this.swoopTarget[1] + 6; gz = this.swoopTarget[2]; }
    }
    const dx = gx - this.x, dy = gy - this.y, dz = gz - this.z;
    const l = Math.hypot(dx, dy, dz) || 1;
    this.vx = lerp(this.vx, dx / l * .5, .04);
    this.vy = lerp(this.vy, dy / l * .5, .04);
    this.vz = lerp(this.vz, dz / l * .5, .04);
    this.x += this.vx; this.y += this.vy; this.z += this.vz;
    this.yaw = Math.atan2(this.vx, this.vz);
    // contact damage
    if (p && !p.dead) {
      const d = Math.hypot(p.x - this.x, p.y + 1 - this.y, p.z - this.z);
      if (d < 4) { const dd = mobDmg(8); if (dd > 0) p.damage(dd, 'dragon'); const kb = 1.2; p.vx += (p.x - this.x) * kb; p.vy = Math.max(p.vy, .5); p.vz += (p.z - this.z) * kb; }
    }
    // healing from crystals
    if (this.age % 50 === 0 && this.health < this.maxHealth) {
      for (const e of G.entities) {
        if (e.type === 'crystal' && !e.dead) { this.health = Math.min(this.maxHealth, this.health + 1); break; }
      }
    }
    // wing particles
    if (G.settings.particles && this.age % 4 === 0) spawnParticles(this.x, this.y + 1, this.z, 2, [.5, .2, .7]);
    UI.updateBossBar('Ender Dragon', this.health / this.maxHealth);
  }

  // ---------- Rendering: box models ----------
  drawBoxes(verts, cam, alpha, tmp) {
    if (this.type === 'item' || this.type === 'tnt' || this.type === 'falling') return;
    if (this.type === 'xp') { this.drawXPOrb(verts, alpha); return; }
    if (this.type === 'arrow') { this.drawArrow(verts, alpha); return; }
    if (this.type === 'snowball' || this.type === 'egg') { this.drawTinyBox(verts, alpha, this.type === 'egg' ? [.9, .85, .7] : [.95, .97, 1]); return; }
    if (this.type === 'pearl') { this.drawTinyBox(verts, alpha, [.1, .4, .35]); return; }
    if (this.type === 'xp_bottle') { this.drawTinyBox(verts, alpha, [.35, .85, .95]); return; }
    if (this.type === 'wither_skull_proj') { this.drawTinyBox(verts, alpha, [.15, .15, .18], .24); return; }
    if (this.type === 'fireball') { this.drawTinyBox(verts, alpha, [1, .6, .15], .9); return; }
    if (this.type === 'crystal') { this.drawCrystal(verts, alpha); return; }

    const l = this.lightAt();
    const hurt = this.hurtTime > 0 ? 1 : 0;
    const deathRot = this.dead ? Math.min(1, this.deathTime / 15) * Math.PI / 2 : 0;
    const scale = this.babyAge < 0 ? .55 : 1;
    // leg swing interpolated between the last two ticks (see tick(): walkAnimO)
    const wa = this.walkAnimO === undefined ? this.walkAnim : this.walkAnimO + (this.walkAnim - this.walkAnimO) * alpha;
    const ws = this.walkSpeedO === undefined ? this.walkSpeed : this.walkSpeedO + (this.walkSpeed - this.walkSpeedO) * alpha;
    const swing = Math.sin(wa) * Math.min(1, ws * 6);
    const m = this.def.model;
    const C = this.def.colors || {};

    // push rotated+translated colored boxes
    const emit = (parts) => {
      for (const part of parts) this.emitPart(verts, part, alpha, l, hurt, deathRot, scale);
    };

    if (m === 'humanoid') {
      const skin = C.skin, shirt = C.shirt, pants = C.pants;
      const armSwing = this.type === 'zombie' ? -1.4 : swing * .8;
      emit([
        { x: 0, y: 1.5 * scale, z: 0, w: .5 * scale, h: .5 * scale, d: .5 * scale, c: skin, head: true },
        { x: 0, y: .95 * scale, z: 0, w: .56 * scale, h: .66 * scale, d: .3 * scale, c: shirt },
        { x: -.36 * scale, y: 1.06 * scale, z: 0, w: .22 * scale, h: .62 * scale, d: .22 * scale, c: this.type === 'zombie' ? skin : shirt, rx: armSwing },
        { x: .36 * scale, y: 1.06 * scale, z: 0, w: .22 * scale, h: .62 * scale, d: .22 * scale, c: this.type === 'zombie' ? skin : shirt, rx: this.type === 'zombie' ? armSwing : -armSwing },
        { x: -.14 * scale, y: .33 * scale, z: 0, w: .22 * scale, h: .62 * scale, d: .22 * scale, c: pants, rx: swing },
        { x: .14 * scale, y: .33 * scale, z: 0, w: .22 * scale, h: .62 * scale, d: .22 * scale, c: pants, rx: -swing },
      ]);
      // eyes
      emit([
        { x: -.12 * scale, y: 1.58 * scale, z: -.26 * scale, w: .1, h: .06, d: .02, c: [0.05, 0.05, 0.08] },
        { x: .12 * scale, y: 1.58 * scale, z: -.26 * scale, w: .1, h: .06, d: .02, c: [0.05, 0.05, 0.08] },
      ]);
      // MC villager: the signature big nose under the eye line (1:1 look)
      if (this.type === 'villager') emit([
        { x: 0, y: 1.52 * scale, z: -.28 * scale, w: .08, h: .18, d: .07, c: [0.71, 0.52, 0.38] },
      ]);
    } else if (m === 'creeper') {
      const swell = this.fuse >= 0 ? 1 + Math.sin(this.age * .8) * .08 : 1;
      emit([
        { x: 0, y: 1.44 * scale, z: 0, w: .5 * scale, h: .5 * scale, d: .5 * scale, c: C.body, head: true },
        { x: 0, y: .85 * scale, z: 0, w: .46 * scale * swell, h: .8 * scale, d: .3 * scale * swell, c: C.body },
        { x: -.16 * scale, y: .24 * scale, z: -.16 * scale, w: .22 * scale, h: .5 * scale, d: .22 * scale, c: C.dark },
        { x: .16 * scale, y: .24 * scale, z: -.16 * scale, w: .22 * scale, h: .5 * scale, d: .22 * scale, c: C.dark },
        { x: -.16 * scale, y: .24 * scale, z: .16 * scale, w: .22 * scale, h: .5 * scale, d: .22 * scale, c: C.dark },
        { x: .16 * scale, y: .24 * scale, z: .16 * scale, w: .22 * scale, h: .5 * scale, d: .22 * scale, c: C.dark },
      ]);
      // creeper face
      emit([
        { x: -.12 * scale, y: 1.52 * scale, z: -.26 * scale, w: .1, h: .1, d: .02, c: [0, 0, 0] },
        { x: .12 * scale, y: 1.52 * scale, z: -.26 * scale, w: .1, h: .1, d: .02, c: [0, 0, 0] },
        { x: 0, y: 1.36 * scale, z: -.26 * scale, w: .14, h: .16, d: .02, c: [0, 0, 0] },
      ]);
    } else if (m === 'quad') {
      const bodyC = this.sheared && this.type === 'sheep' ? C.head : (this.woolColor ? WOOL_RGB[this.woolColor] : C.body);
      emit([
        { x: 0, y: (this.h * .78) * scale, z: -.42 * scale, w: .42 * scale, h: .42 * scale, d: .42 * scale, c: C.head, head: true },
        { x: 0, y: (this.h * .62) * scale, z: .1 * scale, w: .5 * scale, h: .5 * scale, d: .85 * scale, c: bodyC },
        { x: -.16 * scale, y: .22 * scale, z: -.32 * scale, w: .16 * scale, h: .44 * scale, d: .16 * scale, c: C.legs, rx: swing },
        { x: .16 * scale, y: .22 * scale, z: -.32 * scale, w: .16 * scale, h: .44 * scale, d: .16 * scale, c: C.legs, rx: -swing },
        { x: -.16 * scale, y: .22 * scale, z: .42 * scale, w: .16 * scale, h: .44 * scale, d: .16 * scale, c: C.legs, rx: -swing },
        { x: .16 * scale, y: .22 * scale, z: .42 * scale, w: .16 * scale, h: .44 * scale, d: .16 * scale, c: C.legs, rx: swing },
      ]);
      if (this.type === 'cow') emit([{ x: 0, y: this.h * .62 * scale, z: .1 * scale, w: .52, h: .3, d: .6, c: C.spots }]);
      if (this.type === 'pig') emit([
        { x: 0, y: this.h * .78 * scale, z: -.68 * scale, w: .16, h: .12, d: .06, c: [0.95, 0.7, 0.75] },
      ]);
      // eyes on the head's front face — same dark-box style as the humanoid
      // avatar eyes. MC placement: pig high above the snout, sheep/cow upper sides
      const eyeY = this.type === 'pig' ? (this.h * .78 + .12) * scale : (this.h * .78 + .08) * scale;
      const eyeX = this.type === 'pig' ? .12 * scale : .15 * scale;
      emit([
        { x: -eyeX, y: eyeY, z: -.64 * scale, w: .09, h: .07, d: .03, c: [0.04, 0.04, 0.07] },
        { x: eyeX, y: eyeY, z: -.64 * scale, w: .09, h: .07, d: .03, c: [0.04, 0.04, 0.07] },
      ]);
    } else if (m === 'chicken') {
      emit([
        { x: 0, y: .58 * scale, z: -.18 * scale, w: .24 * scale, h: .3 * scale, d: .24 * scale, c: C.head, head: true },
        { x: 0, y: .56 * scale, z: -.36 * scale, w: .1, h: .08, d: .12, c: C.beak },
        { x: 0, y: .3 * scale, z: 0, w: .3 * scale, h: .3 * scale, d: .4 * scale, c: C.body },
        { x: -.12 * scale, y: .3 * scale, z: .28 * scale, w: .1 * scale, h: .1 * scale, d: .34, c: [0.85, 0.55, 0.3], rx: -swing },
        { x: .12 * scale, y: .3 * scale, z: .28 * scale, w: .1 * scale, h: .1 * scale, d: .34, c: [0.85, 0.55, 0.3], rx: -swing },
        { x: -.08 * scale, y: .08 * scale, z: 0, w: .06, h: .16, d: .06, c: C.legs },
        { x: .08 * scale, y: .08 * scale, z: 0, w: .06, h: .16, d: .06, c: C.legs },
      ]);
      // chicken eyes sit on the SIDES of the head just above the beak (MC)
      emit([
        { x: -.125 * scale, y: .62 * scale, z: -.26 * scale, w: .02, h: .04, d: .05, c: [0.06, 0.06, 0.09] },
        { x: .125 * scale, y: .62 * scale, z: -.26 * scale, w: .02, h: .04, d: .05, c: [0.06, 0.06, 0.09] },
      ]);
    } else if (m === 'spider') {
      emit([
        { x: 0, y: .45 * scale, z: -.5 * scale, w: .4 * scale, h: .4 * scale, d: .4 * scale, c: this.def.colors.head, head: true },
        { x: 0, y: .5 * scale, z: .25 * scale, w: .55 * scale, h: .42 * scale, d: .7 * scale, c: C.body },
      ]);
      for (let i = 0; i < 4; i++) {
        const zz = -.2 + i * .22;
        const ph = swing * (i % 2 ? 1 : -1);
        emit([
          { x: -.5 * scale, y: .4 * scale, z: zz, w: .55 * scale, h: .1, d: .1, c: C.body, rz: .5 + ph * .3, pivot: [-.25, 0, 0] },
          { x: .5 * scale, y: .4 * scale, z: zz, w: .55 * scale, h: .1, d: .1, c: C.body, rz: -.5 - ph * .3, pivot: [.25, 0, 0] },
        ]);
      }
      // red eyes
      emit([
        { x: -.1, y: .52, z: -.71, w: .06, h: .06, d: .02, c: [.8, 0, 0] },
        { x: .1, y: .52, z: -.71, w: .06, h: .06, d: .02, c: [.8, 0, 0] },
      ]);
    } else if (m === 'ghast') {
      const flap = Math.sin(this.age * .15) * .1;
      emit([{ x: 0, y: 2 * scale, z: 0, w: 4 * scale, h: 3.6 * scale, d: 4 * scale, c: C.body }]);
      // tentacles
      for (let i = 0; i < 9; i++) {
        const ox = ((i % 3) - 1) * 1.2, oz = ((i / 3 | 0) - 1) * 1.2;
        emit([{ x: ox * scale, y: (-0.2 + flap) * scale, z: oz * scale, w: .3, h: 1.4, d: .3, c: [0.85, 0.85, 0.85] }]);
      }
      emit([
        { x: -.7, y: 2.4, z: -2.05, w: .3, h: .3, d: .05, c: [.1, .1, .1] },
        { x: .7, y: 2.4, z: -2.05, w: .3, h: .3, d: .05, c: [.1, .1, .1] },
      ]);
    } else if (m === 'dragon') {
      const flap = Math.sin(this.age * .12);
      emit([
        { x: 0, y: 1.2, z: 0, w: 1.6, h: 1.2, d: 3.4, c: C.body },
        { x: 0, y: 1.4, z: -2.1, w: .8, h: .7, d: 1.2, c: C.body, head: true },
        { x: 0, y: 1.4, z: -2.9, w: .4, h: .3, d: .8, c: [.3, .1, .1] },
        { x: -1.4, y: 1.6, z: .2, w: 2.6, h: .15, d: 2.2, c: C.wing, rz: flap * .5, pivot: [1.3, 0, 0] },
        { x: 1.4, y: 1.6, z: .2, w: 2.6, h: .15, d: 2.2, c: C.wing, rz: -flap * .5, pivot: [-1.3, 0, 0] },
        { x: 0, y: 1.1, z: 2.2, w: .5, h: .4, d: 2.4, c: C.body },
      ]);
      emit([
        { x: -.25, y: 1.6, z: -2.7, w: .15, h: .15, d: .05, c: [1, .3, .3] },
        { x: .25, y: 1.6, z: -2.7, w: .15, h: .15, d: .05, c: [1, .3, .3] },
      ]);
    } else if (m === 'wither') {
      emit([
        { x: 0, y: 2.4, z: 0, w: .5, h: .5, d: .5, c: C.body, head: true },
        { x: -.6, y: 2.2, z: 0, w: .4, h: .4, d: .4, c: C.body, head: true },
        { x: .6, y: 2.2, z: 0, w: .4, h: .4, d: .4, c: C.body, head: true },
        { x: 0, y: 1.2, z: 0, w: .35, h: 1.2, d: .3, c: C.body },
        { x: -.7, y: 1.7, z: 0, w: 1.1, h: .12, d: .12, c: C.body, rz: .5 },
        { x: .7, y: 1.7, z: 0, w: 1.1, h: .12, d: .12, c: C.body, rz: -.5 },
      ]);
      emit([
        { x: -.6, y: 2.24, z: -.21, w: .08, h: .08, d: .02, c: [0, 0, 0] },
        { x: .6, y: 2.24, z: -.21, w: .08, h: .08, d: .02, c: [0, 0, 0] },
        { x: 0, y: 2.5, z: -.26, w: .3, h: .1, d: .02, c: [0, 0, 0] },
      ]);
    } else if (m === 'boat') {
      const c = [0.55, 0.42, 0.26];
      emit([
        { x: 0, y: .25, z: -.55, w: 1.1, h: .3, d: .15, c },
        { x: 0, y: .25, z: .55, w: 1.1, h: .3, d: .15, c },
        { x: -.55, y: .25, z: 0, w: .15, h: .3, d: 1.1, c },
        { x: .55, y: .25, z: 0, w: .15, h: .3, d: 1.1, c },
        { x: 0, y: .1, z: 0, w: .9, h: .12, d: .95, c: [0.4, 0.3, 0.18] },
      ]);
    } else if (m === 'cart') {
      const c = [0.5, 0.5, 0.53];
      emit([
        { x: 0, y: .3, z: 0, w: .9, h: .4, d: 1.1, c },
        { x: 0, y: .3, z: 0, w: .75, h: .25, d: .95, c: [0.25, 0.25, 0.27] },
        { x: -.4, y: .08, z: -.35, w: .12, h: .16, d: .12, c: [.2, .2, .2] },
        { x: .4, y: .08, z: -.35, w: .12, h: .16, d: .12, c: [.2, .2, .2] },
        { x: -.4, y: .08, z: .35, w: .12, h: .16, d: .12, c: [.2, .2, .2] },
        { x: .4, y: .08, z: .35, w: .12, h: .16, d: .12, c: [.2, .2, .2] },
      ]);
    } else if (m === 'player_model') {
      emit([{ x: 0, y: 1.5, z: 0, w: .5, h: .5, d: .5, c: C.skin, head: true }]);
    }
  }

  lightAt() {
    const l = G.world.getLight(Math.floor(this.rx), Math.floor(this.ry + 1), Math.floor(this.rz));
    const sky = (l >> 4) / 15, blk = (l & 15) / 15;
    const dayBr = G.dimension === 1 ? 0.12 : (G.dimension === 2 ? 0.4 : dayBrightness());
    return clamp(0.1 + 0.9 * Math.max(sky * dayBr, blk), 0.12, 1);
  }

  emitPart(verts, part, alpha, light, hurt, deathRot, bodyScale) {
    // builds 6 faces of a rotated box, position interpolated in entity local space then rotated by entity yaw
    const hw = (part.w || .3) / 2, hh = (part.h || .3) / 2, hd = (part.d || .3) / 2;
    const c = part.c || [1, 1, 1];
    const rr = hurt ? Math.min(1, c[0] + .5) : c[0], rg = hurt ? c[1] * .5 : c[1], rb = hurt ? c[2] * .5 : c[2];
    // body yaw interpolated between ticks (shortest arc) — no 20 Hz turn snapping
    const ryaw = this.yawO === undefined ? (this.yaw || 0)
      : this.yawO + (() => { let d = (this.yaw || 0) - this.yawO; while (d > Math.PI) d -= Math.PI * 2; while (d < -Math.PI) d += Math.PI * 2; return d * alpha; })();
    const bodyYaw = ryaw + Math.PI;
    const partYaw = part.ry || 0;
    const pitch = part.head ? (this.pitch || 0) : (part.rx || 0);
    const zrot = part.rz || 0;
    const bcs = Math.cos(bodyYaw), bsn = Math.sin(bodyYaw);
    const pcs = Math.cos(partYaw), psn = Math.sin(partYaw);
    const cp = Math.cos(pitch), sp = Math.sin(pitch);
    const cz = Math.cos(zrot), sz = Math.sin(zrot);
    const cdr = Math.cos(deathRot || 0), sdr = Math.sin(deathRot || 0);
    const ox = part.x || 0, oy = part.y || 0, oz = part.z || 0;
    const pvx = part.pivot ? part.pivot[0] : 0, pvy = part.pivot ? part.pivot[1] : 0, pvz = part.pivot ? part.pivot[2] : 0;
    const tf = (x, y, z) => {
      // 1. rotate around part pivot (local pitch/roll/yaw)
      let ax = x - pvx, ay = y - pvy, az = z - pvz;
      if (zrot) { const t = cz * ax - sz * ay; ay = sz * ax + cz * ay; ax = t; }
      if (pitch) { const t = cp * ay - sp * az; az = sp * ay + cp * az; ay = t; }
      if (partYaw) { const t = pcs * ax + psn * az; az = -psn * ax + pcs * az; ax = t; }
      ax += pvx + ox; ay += pvy + oy; az += pvz + oz;
      // 2. death fall-over rotation
      if (deathRot) { const t = cdr * ax - sdr * ay; ay = sdr * ax + cdr * ay; ax = t; }
      // 3. rotate entire entity by bodyYaw around (this.rx, this.ry, this.rz)
      const wx = bcs * ax + bsn * az;
      const wz = -bsn * ax + bcs * az;
      return [this.rx + wx, this.ry + ay, this.rz + wz];
    };
    const faces = [
      { n: 'top', pts: [[-hw, hh, -hd], [hw, hh, -hd], [hw, hh, hd], [-hw, hh, hd]], s: 1 },
      { n: 'bottom', pts: [[-hw, -hh, hd], [hw, -hh, hd], [hw, -hh, -hd], [-hw, -hh, -hd]], s: .55 },
      { n: 'north', pts: [[-hw, -hh, -hd], [hw, -hh, -hd], [hw, hh, -hd], [-hw, hh, -hd]], s: .8 },
      { n: 'south', pts: [[hw, -hh, hd], [-hw, -hh, hd], [-hw, hh, hd], [hw, hh, hd]], s: .8 },
      { n: 'east', pts: [[hw, -hh, -hd], [hw, -hh, hd], [hw, hh, hd], [hw, hh, -hd]], s: .65 },
      { n: 'west', pts: [[-hw, -hh, hd], [-hw, -hh, -hd], [-hw, hh, -hd], [-hw, hh, hd]], s: .65 },
    ];
    for (const f of faces) {
      const P = f.pts.map(p => tf(p[0], p[1], p[2]));
      const shade = f.s * light;
      const R = rr * shade, Gg = rg * shade, Bb = rb * shade;
      const idxs = [0, 1, 2, 2, 3, 0];
      for (const i of idxs) verts.push(P[i][0], P[i][1], P[i][2], R, Gg, Bb, 1);
    }
  }

  drawItem(verts, alpha) {
    const t = this.age * .05;
    const bob = Math.sin(t * 2) * .06;
    const y = this.ry + .25 + bob;
    const bl = ITEMS[this.itemStack.id];
    // MC: block drops are spinning mini-cubes with the block's own colors
    if (bl && bl.placeBlock != null) {
      const pal = TEX.particleColor(bl.placeBlock);
      if (!this._color) {
        let r = 0, g = 0, b = 0;
        for (const c of pal) { r += c[0]; g += c[1]; b += c[2]; }
        this._color = [r / pal.length, g / pal.length, b / pal.length];
      }
      this.emitTinyBox(verts, this.rx, y, this.rz, 0.2, this._color, alpha, t);
      return;
    }
    // non-block items: flat spinning sprite with the item's true icon colors
    if (!this._color) {
      const def2 = ITEMS[this.itemStack.id];
      const painter = ITEM_ICON_PAINTERS[def2.key];
      let col = [0.7, 0.7, 0.7];
      if (painter) {
        const img = new ImageData(16, 16);
        const t2 = makePaintCtx(img, hashStr('item:' + def2.key));
        painter(t2);
        let r = 0, g = 0, b = 0, n = 0;
        for (let i = 3; i < img.data.length; i += 4) {
          if (img.data[i] > 100) { r += img.data[i - 3]; g += img.data[i - 2]; b += img.data[i - 1]; n++; }
        }
        if (n) col = [r / n / 255, g / n / 255, b / n / 255];
      } else if (def2.placeBlock != null) {
        const pal = TEX.particleColor(def2.placeBlock);
        const c2 = pal[0];
        col = c2;
      }
      this._color = col;
    }
    const c = this._color;
    const s = .18;
    const csp = Math.cos(t), snp = Math.sin(t);
    const P = [];
    for (const X of [-s, s]) for (const Y of [-s, s]) P.push([this.rx + X * csp, y + Y, this.rz + X * snp]);
    const q = (a, b, c2, d2, sh) => {
      for (const p of [a, b, c2, a, c2, d2]) verts.push(p[0], p[1], p[2], c[0] * sh, c[1] * sh, c[2] * sh, alpha);
    };
    q(P[0], P[1], P[3], P[2], 1);
    q(P[1], P[0], P[2], P[3], .7);
  }

  drawXPOrb(verts, alpha) {
    const t = this.age * .1 + this.x;
    const r = .5 + Math.sin(t) * .5;
    const g = 1, b = .2 + Math.sin(t * 1.3) * .2;
    const s = .09 + (this.value > 3 ? .05 : 0);
    const y = this.ry + .2 + Math.sin(t * 1.5) * 0.04;
    const c = [r, g, b];
    this.emitTinyBox(verts, this.rx, y, this.rz, s, c, 1, t * 0.5);
  }

  drawArrow(verts, alpha) {
    const yaw = this.inGround ? this.yaw : Math.atan2(this.vx, this.vz);
    const pitch = this.inGround ? this.pitch : -Math.atan2(this.vy, Math.hypot(this.vx, this.vz));
    const cs = Math.cos(yaw), sn = Math.sin(yaw);
    const cp = Math.cos(pitch), sp = Math.sin(pitch);
    const tf = (x, y, z) => {
      const ay = cp * y - sp * z;
      const az1 = sp * y + cp * z;
      const ax = cs * x + sn * az1;
      const az = -sn * x + cs * az1;
      return [this.rx + ax, this.ry + .1 + ay, this.rz + az];
    };
    const hw = 0.035, hh = 0.035, hd = 0.24;
    const c = [.6, .45, .25];
    const quads = [
      [[-hw, hh, -hd], [hw, hh, -hd], [hw, hh, hd], [-hw, hh, hd], 1],
      [[-hw, -hh, hd], [hw, -hh, hd], [hw, -hh, -hd], [-hw, -hh, -hd], .6],
      [[-hw, -hh, -hd], [hw, -hh, -hd], [hw, hh, -hd], [-hw, hh, -hd], .85],
      [[hw, -hh, hd], [-hw, -hh, hd], [-hw, hh, hd], [hw, hh, hd], .85],
      [[hw, -hh, -hd], [hw, -hh, hd], [hw, hh, hd], [hw, hh, -hd], .7],
      [[-hw, -hh, hd], [-hw, -hh, -hd], [-hw, hh, -hd], [-hw, hh, hd], .7],
    ];
    for (const q of quads) {
      const P = [tf(q[0][0], q[0][1], q[0][2]), tf(q[1][0], q[1][1], q[1][2]), tf(q[2][0], q[2][1], q[2][2]), tf(q[3][0], q[3][1], q[3][2])];
      const sh = q[4];
      for (const i of [0, 1, 2, 2, 3, 0]) verts.push(P[i][0], P[i][1], P[i][2], c[0] * sh, c[1] * sh, c[2] * sh, 1);
    }
  }

  emitTinyBox(verts, x, y, z, s, c, alpha, yaw = 0) {
    const cs = Math.cos(yaw), sn = Math.sin(yaw);
    const tf = (X, Y, Z) => [x + cs * X + sn * Z, y + Y, z + -sn * X + cs * Z];
    const h = s, w = s;
    const quads = [
      [[-w, h, -w], [w, h, -w], [w, h, w], [-w, h, w], 1],
      [[-w, -h, w], [w, -h, w], [w, -h, -w], [-w, -h, -w], .6],
      [[-w, -h, -w], [w, -h, -w], [w, h, -w], [-w, h, -w], .85],
      [[w, -h, w], [-w, -h, w], [-w, h, w], [w, h, w], .85],
      [[w, -h, -w], [w, -h, w], [w, h, w], [w, h, -w], .7],
      [[-w, -h, w], [-w, -h, -w], [-w, h, -w], [-w, h, w], .7],
    ];
    for (const q of quads) {
      const P = [tf(q[0][0], q[0][1], q[0][2]), tf(q[1][0], q[1][1], q[1][2]), tf(q[2][0], q[2][1], q[2][2]), tf(q[3][0], q[3][1], q[3][2])];
      const sh = q[4];
      for (const i of [0, 1, 2, 2, 3, 0]) verts.push(P[i][0], P[i][1], P[i][2], c[0] * sh, c[1] * sh, c[2] * sh, 1);
    }
  }

  drawTinyBox(verts, alpha, c, scale = .18) {
    this.emitTinyBox(verts, this.rx, this.ry + scale, this.rz, scale, c, alpha);
  }

  drawTNT(verts, alpha) {
    const flash = Math.floor(this.age / 5) % 2 === 0;
    const c = flash ? [1, 1, 1] : [.7, .18, .15];
    this.emitTinyBox(verts, this.rx, this.ry + .49, this.rz, .49, c, alpha);
  }

  drawFalling(verts, alpha) {
    const pal = TEX.particleColor(this.blockId);
    const c = pal[(Math.random() * pal.length) | 0];
    this.emitTinyBox(verts, this.rx, this.ry + .49, this.rz, .49, c, alpha);
  }

  drawCrystal(verts, alpha) {
    const t = this.age * .04;
    const bob = Math.sin(t) * .15;
    const c = [1, .95, .8];
    this.emitTinyBox(verts, this.rx, this.ry + 1.6 + bob, this.rz, .45, c, alpha * (.8 + Math.sin(t * 2) * .2));
  }
}

const WOOL_RGB = {
  white: [.91, .93, .93], orange: [.94, .46, .08], magenta: [.74, .27, .7], light_blue: [.23, .69, .85],
  yellow: [.97, .77, .15], lime: [.44, .73, .1], pink: [.93, .55, .67], gray: [.24, .27, .28],
  light_gray: [.56, .56, .53], cyan: [.08, .54, .57], purple: [.47, .16, .67], blue: [.21, .22, .62],
  brown: [.45, .28, .16], green: [.33, .43, .11], red: [.63, .15, .13], black: [.08, .08, .1],
};

// ---------- natural spawning ----------
// Villager.java restock(): every offer's uses reset — MC restocks 2× per day
// (morning + afternoon at the workstation); we key it off the world clock
function villagerRestock(v) {
  const t = Math.floor(G.world.time % DAY_TICKS);
  const day = Math.floor(G.world.time / DAY_TICKS);
  const key = day * 2 + (t < DAY_TICKS / 2 ? 0 : 1);
  if (v._restockKey !== key) {
    const first = v._restockKey === undefined;
    v._restockKey = key;
    if (!first && v.offers) for (const o of v.offers) o.uses = 0; // MerchantOffer.resetUses()
  }
}

const SpawnSystem = {
  timer: 0,
  tick() {
    if (--this.timer > 0) return;
    this.timer = 20;
    const p = G.player;
    if (!p) return;
    let hostiles = 0, passives = 0;
    for (const e of G.entities) {
      if (e.dead || !e.def) continue;
      if (e.def.hostile && !e.def.dragon) hostiles++;
      else if (e.def.passive) passives++;
    }
    const isNight = !isDaytime();
    // MC: peaceful difficulty spawns NO hostile mobs and existing ones
    // despawn instantly (that was a game-mode check before — a dead branch,
    // since 'peaceful' is a difficulty, not a game mode)
    if (G.difficulty === 'peaceful') {
      for (const e of G.entities) {
        if (!e.dead && e.def && e.def.hostile && !e.def.noDespawn) e.dead = true;
      }
    }
    // hostile spawn attempts
    if (G.difficulty !== 'peaceful' && hostiles < (isNight ? 24 : 8) && G.dimension === 0) {
      for (let i = 0; i < 6; i++) this.trySpawn(p, true);
    }
    if (G.dimension === 1) {
      if (G.difficulty !== 'peaceful' && hostiles < 6) for (let i = 0; i < 3; i++) this.trySpawnNether(p);
    }
    if (passives < 12 && G.dimension === 0) this.trySpawn(p, false);
    // despawn far mobs
    for (const e of G.entities) {
      if (e.dead || !e.def.model || e.def.dragon || e.def.noDespawn) continue;
      const d = Math.hypot(e.x - p.x, e.z - p.z);
      if (d > 110 && (e.def.hostile || e.type === 'ghast')) e.dead = true;
      else if (d > 140) e.dead = true;
    }
  },
  findGround(x, z, minY, maxY) {
    for (let y = maxY; y > minY; y--) {
      const id = G.world.getBlock(Math.floor(x), y, Math.floor(z));
      if (id > 0 && BLOCKS[id].solid) return y + 1;
    }
    return -1;
  },
  trySpawn(p, hostile) {
    const ang = rand() * Math.PI * 2;
    const dist = 24 + rand() * 30;
    const x = Math.floor(p.x + Math.cos(ang) * dist);
    const z = Math.floor(p.z + Math.sin(ang) * dist);
    const y = this.findGround(x, z, 8, WORLD_H - 2);
    if (y < 0) return;
    const ground = G.world.getBlock(x, y - 1, z);
    if (ground <= 0 || !BLOCKS[ground].solid) return;
    const sky = G.world.skyLight(x, y, z);
    const blk = G.world.blockLight(x, y, z);
    if (hostile) {
      if (Math.max(sky * (isDaytime() ? 1 : 0), blk) > 7) return;
      const types = ['zombie', 'zombie', 'skeleton', 'creeper', 'spider'];
      if (rand() < .04) types.push('enderman');
      const type = types[(rand() * types.length) | 0];
      // space check
      const d = MOB_DEFS[type];
      if (G.world.getBlock(x, y + Math.ceil(d.h) - 1, z) !== 0) return;
      spawnEntity(type, x + .5, y, z + .5);
    } else {
      if (sky < 9) return;
      if (ground !== B.grass_block && ground !== B.podzol) return;
      const types = ['pig', 'cow', 'sheep', 'chicken'];
      const type = types[(rand() * types.length) | 0];
      const n = randInt(2, 4);
      for (let i = 0; i < n; i++) spawnEntity(type, x + .5 + (rand() - .5) * 3, y + 1, z + .5 + (rand() - .5) * 3);
    }
  },
  trySpawnNether(p) {
    const ang = rand() * Math.PI * 2;
    const dist = 24 + rand() * 30;
    const x = Math.floor(p.x + Math.cos(ang) * dist);
    const z = Math.floor(p.z + Math.sin(ang) * dist);
    for (let y = 36; y < 100; y++) {
      if (G.world.getBlock(x, y, z) === 0 && G.world.getBlock(x, y + 4, z) === 0 && G.world.getBlock(x, y - 1, z) === B.netherrack) {
        spawnEntity(rand() < .3 ? 'ghast' : 'zombie', x + .5, y, z + .5);
        return;
      }
    }
  },
};

// gravity blocks: monkey-patch neighbor update to trigger falling sand/gravel
const _origWorldUpdateNeighbors = World_updateNeighbors;
World_updateNeighbors = function (wx, wy, wz, world) {
  _origWorldUpdateNeighbors(wx, wy, wz, world);
  // check block above the changed position for gravity blocks
  for (let y = wy + 1; y < WORLD_H; y++) {
    const id = world.getBlock(wx, y, wz);
    if (id <= 0) break;
    const bl = BLOCKS[id];
    if (bl.gravity) {
      const below = world.getBlock(wx, y - 1, wz);
      if (below === 0 || !BLOCKS[below].solid) {
        world.setBlock(wx, y, wz, 0, 0, { noUpdate: true, noNet: false });
        const e = new Entity('falling', wx + .5, y, wz + .5, MOB_DEFS.falling, {});
        e.blockId = id;
        G.entities.push(e);
      } else break;
    } else if (id > 0 && BLOCKS[id].solid) break;
  }
  // the changed block itself
  const id = world.getBlock(wx, wy, wz);
  if (id > 0 && BLOCKS[id].gravity) {
    const below = world.getBlock(wx, wy - 1, wz);
    if (below === 0 || !BLOCKS[below].solid) {
      world.setBlock(wx, wy, wz, 0, 0, { noUpdate: true });
      const e = new Entity('falling', wx + .5, wy, wz + .5, MOB_DEFS.falling, {});
      e.blockId = id;
      G.entities.push(e);
    }
  }
};

function isDaytime() {
  const t = ((G.world.time % DAY_TICKS) + DAY_TICKS) % DAY_TICKS;
  return t < 12500 && t > 1500;
}
function dayBrightness() {
  const t = ((G.world.time % DAY_TICKS) + DAY_TICKS) % DAY_TICKS;
  return clamp(Math.sin(t / DAY_TICKS * Math.PI * 2) * 1.4 + 0.6, 0.06, 1);
}

// ============================================================================
// Part 11: Redstone power system, TNT/explosions, block interactions
// (doors, levers, buttons, plates, note blocks, beds, bone meal, portals)
// ============================================================================
const Redstone = {
  // Meta layouts:
  // redstone_wire: high nibble = power (0-15), low nibble = connection mask (mesh time)
  // lever: bit0 = on
  // button: bit0 = pressed (timed)
  // repeater: bits0-1 delay, bit2 = powered out
  // redstone_lamp / redstone_torch: bit0 lit
  pendingUpdates: new Set(),
  buttonTimers: [],   // [x,y,z,ticksLeft]

  isPowerSource(id, meta, world, x, y, z) {
    if (id === B.redstone_block) return 15;
    if (id === B.lever && (meta & 1)) return 15;
    if (id === B.stone_button && (meta & 1)) return 15;
    if (id === B.redstone_torch && !(meta & 1)) return 15;
    if (id === B.repeater && (meta & 4)) return 15;
    return 0;
  },

  // compute emitted power into a wire from adjacent sources
  wirePower(world, x, y, z) {
    let p = 0;
    for (const [dx, dy, dz] of NEIGH6) {
      const nx = x + dx, ny = y + dy, nz = z + dz;
      const nid = world.getBlock(nx, ny, nz);
      if (nid <= 0) continue;
      const nm = world.getMeta(nx, ny, nz);
      if (nid === B.redstone_wire) {
        p = Math.max(p, (nm >> 4) - 1);
      } else {
        p = Math.max(p, this.isPowerSource(nid, nm, world, nx, ny, nz));
        // strong power from repeater facing into this wire
        if (nid === B.repeater && (nm & 4)) {
          const facing = nm & 3;
          const off = [[0, 1], [-1, 0], [0, -1], [1, 0]][facing];
          if (dx === off[0] && dz === off[1] && dy === 0) p = 15;
        }
        // strong power from an opaque block directly above an active redstone torch
        if (BLOCKS[nid] && BLOCKS[nid].opaque) {
          const belowN = world.getBlock(nx, ny - 1, nz);
          const belowM = world.getMeta(nx, ny - 1, nz);
          if (belowN === B.redstone_torch && !(belowM & 1)) p = 15;
        }
      }
    }
    return clamp(p, 0, 15);
  },

  // flood-fill recompute of wire network around a change point
  updateNetwork(world, x, y, z) {
    if (this._inUpdate) return; // recursion guard: setBlock inside triggers neighbor updates
    this._inUpdate = true;
    try { this._updateNetworkInner(world, x, y, z); }
    finally { this._inUpdate = false; }
  },
  _updateNetworkInner(world, x, y, z) {
    // collect wire network via BFS from any wire at/adjacent to (x,y,z)
    const seeds = [];
    if (world.getBlock(x, y, z) === B.redstone_wire) seeds.push([x, y, z]);
    for (const [dx, dy, dz] of NEIGH6) {
      if (world.getBlock(x + dx, y + dy, z + dz) === B.redstone_wire) seeds.push([x + dx, y + dy, z + dz]);
    }
    const network = new Set();
    const q = [...seeds];
    while (q.length) {
      const [cx2, cy2, cz2] = q.pop();
      const k = cx2 + ',' + cy2 + ',' + cz2;
      if (network.has(k)) continue;
      network.add(k);
      for (const [dx, dy, dz] of NEIGH6) {
        const nx = cx2 + dx, ny = cy2 + dy, nz = cz2 + dz;
        if (world.getBlock(nx, ny, nz) === B.redstone_wire) q.push([nx, ny, nz]);
      }
    }
    // iterate to fixed point (max 16 passes)
    let changed = true, pass = 0;
    while (changed && pass++ < 16) {
      changed = false;
      for (const k of network) {
        const [cx2, cy2, cz2] = k.split(',').map(Number);
        const m = world.getMeta(cx2, cy2, cz2);
        const cur = m >> 4;
        let target;
        if (network.size === 1) target = this.wirePower(world, cx2, cy2, cz2);
        else target = this.wirePower(world, cx2, cy2, cz2);
        if (target !== cur) {
          world.setBlock(cx2, cy2, cz2, B.redstone_wire, (target << 4) | (m & 15), { noUpdate: true, noLight: true });
          changed = true;
        }
      }
    }
    // update consumers adjacent to network
    const consumers = new Set();
    for (const k of network) {
      const [cx2, cy2, cz2] = k.split(',').map(Number);
      const m = world.getMeta(cx2, cy2, cz2);
      const pow = m >> 4;
      for (const [dx, dy, dz] of NEIGH6) {
        const nx = cx2 + dx, ny = cy2 + dy, nz = cz2 + dz;
        const nid = world.getBlock(nx, ny, nz);
        if (nid <= 0) continue;
        consumers.add(nx + ',' + ny + ',' + nz);
      }
    }
    // also consumers adjacent to the original change
    for (const [dx, dy, dz] of NEIGH6) consumers.add((x + dx) + ',' + (y + dy) + ',' + (z + dz));
    consumers.add(x + ',' + y + ',' + z);
    for (const k of consumers) this.updateConsumer(world, ...k.split(',').map(Number));
  },

  isBlockPowered(world, x, y, z) {
    // is this position receiving power from adjacent wires/sources?
    for (const [dx, dy, dz] of NEIGH6) {
      const nx = x + dx, ny = y + dy, nz = z + dz;
      const nid = world.getBlock(nx, ny, nz);
      if (nid <= 0) continue;
      const nm = world.getMeta(nx, ny, nz);
      if (nid === B.redstone_wire && (nm >> 4) > 0) return true;
      const src = this.isPowerSource(nid, nm, world, nx, ny, nz);
      if (src > 0 && nid !== B.redstone_torch) return true;
    }
    return false;
  },

  updateConsumer(world, x, y, z) {
    const id = world.getBlock(x, y, z);
    if (id <= 0) return;
    const m = world.getMeta(x, y, z);
    switch (id) {
      case B.redstone_lamp: {
        const powered = this.isBlockPowered(world, x, y, z);
        if (powered !== !!(m & 1)) world.setBlock(x, y, z, id, (m & ~1) | (powered ? 1 : 0), { noUpdate: true });
        break;
      }
      case B.redstone_torch: {
        // torch turns off when its support block is powered
        const supportPowered = this.isBlockPowered(world, x, y - 1, z);
        const lit = !supportPowered;
        if (lit !== !(m & 1)) world.setBlock(x, y, z, id, (m & ~1) | (lit ? 0 : 1), { noUpdate: true });
        break;
      }
      case B.tnt: {
        if (this.isBlockPowered(world, x, y, z)) igniteTNT(world, x, y, z);
        break;
      }
      case B.piston:
      case B.sticky_piston: {
        // 1:1 PistonBaseBlock.checkIfExtend & PistonStructureResolver (MAX_PUSH_DEPTH = 12)
        const powered = this.isBlockPowered(world, x, y, z);
        const extended = !!(m & 4);
        const facing = m & 3; // 0=south(+z), 1=west(-x), 2=north(-z), 3=east(+x)
        const dir = [[0, 0, 1], [-1, 0, 0], [0, 0, -1], [1, 0, 0]][facing];
        if (powered && !extended) {
          // Resolve line of up to 12 pushable blocks
          const line = [];
          let canPush = true;
          for (let step = 1; step <= 13; step++) {
            const tx = x + dir[0] * step, ty = y + dir[1] * step, tz = z + dir[2] * step;
            const tid = world.getBlock(tx, ty, tz);
            if (tid === 0 || (BLOCKS[tid] && BLOCKS[tid].fluid)) break;
            if (tid < 0 || BLOCKS[tid].hardness < 0 || tid === B.obsidian || tid === B.crying_obsidian || BLOCKS[tid].tileEntity) {
              canPush = false;
              break;
            }
            if (step > 12) { canPush = false; break; }
            line.push([tx, ty, tz, tid, world.getMeta(tx, ty, tz)]);
          }
          if (canPush) {
            for (let i = line.length - 1; i >= 0; i--) {
              const [tx, ty, tz, tid, tm] = line[i];
              world.setBlock(tx + dir[0], ty + dir[1], tz + dir[2], tid, tm, { noUpdate: true });
              if (i === 0) world.setBlock(tx, ty, tz, 0, 0, { noUpdate: true });
            }
            world.setBlock(x, y, z, id, m | 4, { noUpdate: true });
            SFX.playClick(true);
          }
        } else if (!powered && extended) {
          world.setBlock(x, y, z, id, m & ~4, { noUpdate: true });
          // Sticky piston pulls the block at distance 2 back to distance 1
          if (id === B.sticky_piston) {
            const fx1 = x + dir[0], fy1 = y + dir[1], fz1 = z + dir[2];
            const fx2 = x + dir[0] * 2, fy2 = y + dir[1] * 2, fz2 = z + dir[2] * 2;
            const id1 = world.getBlock(fx1, fy1, fz1);
            const id2 = world.getBlock(fx2, fy2, fz2);
            if (id1 === 0 && id2 > 0 && BLOCKS[id2].hardness >= 0 && id2 !== B.obsidian && id2 !== B.crying_obsidian && !BLOCKS[id2].tileEntity) {
              const m2 = world.getMeta(fx2, fy2, fz2);
              world.setBlock(fx1, fy1, fz1, id2, m2, { noUpdate: true });
              world.setBlock(fx2, fy2, fz2, 0, 0, { noUpdate: true });
            }
          }
          SFX.playClick(false);
        }
        break;
      }
      case B.repeater: {
        // input from behind → output after delay
        const facing = m & 3;
        const back = [[0, -1], [1, 0], [0, 1], [-1, 0]][facing]; // opposite of facing dir
        const bx = x - back[0] * 0 + (facing === 0 ? 0 : facing === 1 ? 1 : facing === 2 ? 0 : -1);
        const bz = z + (facing === 0 ? -1 : facing === 2 ? 1 : 0);
        const inId = world.getBlock(bx, y, bz);
        const inM = world.getMeta(bx, y, bz);
        let input = false;
        if (inId === B.redstone_wire && (inM >> 4) > 0) input = true;
        if (this.isPowerSource(inId, inM, world, bx, y, bz) > 0) input = true;
        const out = input;
        if (out !== !!(m & 4)) {
          this.repeaterTimers = this.repeaterTimers || [];
          this.repeaterTimers.push({ x, y, z, target: out, delay: 1 + (m & 3) * 2 });
        }
        break;
      }
      default: break;
    }
  },

  tickRepeaters() {
    if (!this.repeaterTimers) return;
    const next = [];
    for (const t of this.repeaterTimers) {
      t.delay--;
      if (t.delay <= 0) {
        const m = G.world.getMeta(t.x, t.y, t.z);
        const id = G.world.getBlock(t.x, t.y, t.z);
        if (id === B.repeater) {
          G.world.setBlock(t.x, t.y, t.z, id, (m & ~4) | (t.target ? 4 : 0), { noUpdate: true });
          this.updateNetwork(G.world, t.x, t.y, t.z);
        }
      } else next.push(t);
    }
    this.repeaterTimers = next;
  },

  tickButtons() {
    const next = [];
    for (const [x, y, z, t] of this.buttonTimers) {
      if (t - 1 <= 0) {
        const m = G.world.getMeta(x, y, z);
        if (G.world.getBlock(x, y, z) === B.stone_button) {
          G.world.setBlock(x, y, z, B.stone_button, m & ~1, { noUpdate: true });
          this.updateNetwork(G.world, x, y, z);
        }
      } else next.push([x, y, z, t - 1]);
    }
    this.buttonTimers = next;
  },

  tickPlates() {
    // scan loaded pressure plates near player & check entity overlap
    const p = G.player;
    if (!p) return;
    const cx0 = Math.floor((p.x - 24) / CH), cx1 = Math.floor((p.x + 24) / CH);
    const cz0 = Math.floor((p.z - 24) / CH), cz1 = Math.floor((p.z + 24) / CH);
    for (let cx = cx0; cx <= cx1; cx++) for (let cz = cz0; cz <= cz1; cz++) {
      const c = G.world.getChunk(cx, cz);
      if (!c || !c.generated) continue;
      // cheap scan: only the vertical range around the player (plates live near ground)
      const yLo = Math.max(0, Math.floor(p.y) - 16), yHi = Math.min(WORLD_H - 1, Math.floor(p.y) + 16);
      for (let y = yLo; y <= yHi; y += 1) {
        for (let lz = 0; lz < CH; lz += 2) for (let lx = 0; lx < CH; lx += 2) {
          const id = c.blocks[idx3(lx, y, lz)];
          if (id !== B.stone_pressure_plate && id !== B.oak_pressure_plate) continue;
          const wx = cx * CH + lx, wz = cz * CH + lz;
          const m = c.meta[idx3(lx, y, lz)];
          // any entity/player standing on it?
          let pressed = false;
          const check = (e) => {
            if (e.dead || !e.hittable) return;
            if (e.x + e.w / 2 > wx && e.x - e.w / 2 < wx + 1 && e.z + e.w / 2 > wz && e.z - e.w / 2 < wz + 1 && Math.abs(e.y - (y + 1)) < 0.3) pressed = true;
          };
          check(p);
          if (!pressed) for (const e of G.entities) { check(e); if (pressed) break; }
          if (pressed !== !!(m & 1)) {
            G.world.setBlock(wx, y, wz, id, (m & ~1) | (pressed ? 1 : 0), { noUpdate: true });
            SFX.playClick(pressed);
            this.updateNetwork(G.world, wx, y, wz);
          }
        }
      }
    }
  },

  onNeighborChanged(wx, wy, wz) {
    // recompute wire network when any neighbor changes
    this.updateNetwork(G.world, wx, wy, wz);
  },
};

// ---------- TNT & explosions ----------
function igniteTNT(world, x, y, z) {
  world.setBlock(x, y, z, 0, 0, { noUpdate: false });
  const e = new Entity('tnt', x + .5, y, z + .5, MOB_DEFS.tnt, {});
  e.fuse = 80;
  G.entities.push(e);
  SFX.playFuse();
}

function explode(x, y, z, power) {
  SFX.playExplosion();
  const world = G.world;
  const r = Math.ceil(power);
  // block destruction with falloff
  for (let dx = -r; dx <= r; dx++) for (let dy = -r; dy <= r; dy++) for (let dz = -r; dz <= r; dz++) {
    const d = Math.hypot(dx, dy, dz);
    if (d > power * (0.8 + rand() * 0.35)) continue;
    const bx = Math.floor(x) + dx, by = Math.floor(y) + dy, bz = Math.floor(z) + dz;
    const id = world.getBlock(bx, by, bz);
    if (id <= 0) continue;
    const bl = BLOCKS[id];
    if (bl.hardness < 0) continue; // bedrock/obsidian resist
    if (bl.key === 'obsidian' || bl.key === 'crying_obsidian') continue;
    // water dampens
    if (world.getBlock(bx, by + 1, bz) === B.water) continue;
    world.setBlock(bx, by, bz, 0, 0, { noUpdate: true });
    if (bl.fluid) world.setBlock(bx, by, bz, 0, 0, { noUpdate: true });
    if (chance(.28) && bl.drops !== null) {
      const drops = resolveDrops(id, 0, null, 0);
      for (const [key, n] of drops) if (chance(.3)) dropItem(bx + .5, by + .5, bz + .5, key, n);
    }
    // chain reaction
    if (bl.key === 'tnt') igniteTNT(world, bx, by, bz);
  }
  // particles
  spawnParticles(x, y, z, 60, [.45, .42, .4], true);
  spawnParticles(x, y, z, 30, [1, .7, .3], true);
  spawnSmoke(x, y + 1, z, 24, .35);
  // entity damage & knockback (explosion damage is difficulty-scaled for players)
  const hurt = (e, isP) => {
    const d = Math.hypot(e.x - x, (e.y + (isP ? 1 : e.h / 2)) - y, e.z - z);
    if (d > power * 2) return;
    const raw = (1 - d / (power * 2)) * power * 3.5;
    if (isP) {
      const dmg = mobDmg(Math.max(1, Math.round(raw)));
      if (dmg > 0) e.damage(dmg, 'explosion');
    }
    else e.damage(Math.max(1, Math.round(raw)), null, 'explosion');
    const kx = (e.x - x) / (d || 1), ky = ((e.y + 1) - y) / (d || 1), kz = (e.z - z) / (d || 1);
    const kb = (1 - d / (power * 2)) * 1.2;
    e.vx += kx * kb; e.vy += ky * kb * .8 + .2; e.vz += kz * kb;
  };
  for (const e of G.entities) {
    if (e.dead || !e.hittable || e.type === 'item' || e.type === 'xp' || e.type === 'arrow') continue;
    hurt(e, false);
  }
  if (G.player && !G.player.dead) hurt(G.player, true);
}

// ---------- Interactions ----------
function toggleDoor(world, x, y, z) {
  const id = world.getBlock(x, y, z);
  if (BLOCKS[id].shape !== 'door') return;
  const m = world.getMeta(x, y, z);
  const open = (m & 4) ? 0 : 4;
  world.setBlock(x, y, z, id, (m & ~4) | open, { noUpdate: true });
  // other half
  const oy = (m & 8) ? y - 1 : y + 1;
  if (world.getBlock(x, oy, z) === id) {
    const om = world.getMeta(x, oy, z);
    world.setBlock(x, oy, z, id, (om & ~4) | open, { noUpdate: true });
  }
  SFX.playDig('wood');
}

function toggleLever(world, x, y, z) {
  const m = world.getMeta(x, y, z);
  const on = (m & 1) ? 0 : 1;
  world.setBlock(x, y, z, B.lever, (m & ~1) | on, { noUpdate: true });
  SFX.playClick(!!on);
  Redstone.updateNetwork(world, x, y, z);
}

function pressButton(world, x, y, z) {
  const m = world.getMeta(x, y, z);
  world.setBlock(x, y, z, B.stone_button, m | 1, { noUpdate: true });
  SFX.playClick(true);
  Redstone.buttonTimers.push([x, y, z, 20]);
  Redstone.updateNetwork(world, x, y, z);
}

function bumpRepeater(world, x, y, z) {
  const m = world.getMeta(x, y, z);
  const delay = ((m & 3) + 1) & 3;
  world.setBlock(x, y, z, B.repeater, (m & ~3) | delay, { noUpdate: true });
  Chat.actionBar('Repeater delay: ' + (1 + delay * 2) + ' ticks');
  SFX.playClick();
}

function playNoteBlock(world, x, y, z) {
  const m = world.getMeta(x, y, z);
  const semis = (m >> 4) & 15;
  SFX.playNoteBlock(semis - 6);
  // cycle pitch on sneak+use? attack cycles: use breaks. Shift+use cycles handled in useItem? keep: each play cycles
  world.setBlock(x, y, z, B.note_block, ((semis + 1) & 15) << 4, { noUpdate: true });
  spawnParticles(x + .5, y + 1.2, z + .5, 4, [.7, .7, 1], true);
}

function trySleep(x, y, z) {
  const t = ((G.world.time % DAY_TICKS) + DAY_TICKS) % DAY_TICKS;
  const isNight = t >= 12500 || t < 500;
  if (!isNight) { Chat.actionBar('You can only sleep at night'); return; }
  G.player.spawnPoint = [x + .5, y + 1, z + .5];
  Chat.actionBar('Respawn point set. Sleeping...');
  G.world.time = Math.ceil(G.world.time / DAY_TICKS) * DAY_TICKS + 500; // morning
  // clear rain
  G.rain = 0; G.thunder = 0;
  // update all players via net
  if (G.net && G.net.isHostOrSingle) G.net.broadcastTime();
}

function applyBoneMeal(world, x, y, z) {
  const id = world.getBlock(x, y, z);
  const m = world.getMeta(x, y, z);
  if (id === B.wheat) {
    if ((m & 7) >= 7) return false;
    world.setBlock(x, y, z, B.wheat, Math.min(7, (m & 7) + randInt(2, 4)), { noUpdate: true });
    return true;
  }
  for (const w of WOODS) {
    if (id === B[w + '_sapling']) {
      if (chance(.45)) {
        world.setBlock(x, y, z, 0, 0, { noUpdate: true });
        growTree(world, x, y, z, w);
      }
      return true;
    }
    if (id === B[w + '_leaves']) return false;
  }
  if (id === B.grass_block) {
    // grow grass & flowers around
    let did = false;
    for (let i = 0; i < 14; i++) {
      const ox = randInt(-3, 3), oz = randInt(-3, 3);
      const tx = x + ox, tz = z + oz;
      const ty = world.heightAt ? null : null;
      // find surface
      for (let yy = y + 2; yy >= y - 2; yy--) {
        const gid = world.getBlock(tx, yy, tz);
        if (gid === B.grass_block && world.getBlock(tx, yy + 1, tz) === 0) {
          const r = rand();
          if (r < .5) world.setBlock(tx, yy + 1, tz, B.short_grass, 0);
          else if (r < .75) world.setBlock(tx, yy + 1, tz, B.fern, 0);
          else {
            const flowers = ['dandelion', 'poppy', 'cornflower', 'oxeye_daisy', 'red_tulip'];
            world.setBlock(tx, yy + 1, tz, B[flowers[randInt(0, 4)]], 0);
          }
          did = true;
          break;
        }
        if (gid > 0 && BLOCKS[gid].opaque) break;
      }
    }
    return did;
  }
  if (id === B.pumpkin || id === B.melon) return false;
  return false;
}

function growTree(world, x, y, z, woodType) {
  const logId = B[woodType + '_log'], leafId = B[woodType + '_leaves'];
  const h = woodType === 'spruce' ? randInt(6, 9) : randInt(4, 6);
  for (let i = 0; i < h; i++) {
    if (world.getBlock(x, y + i, z) !== 0) return;
  }
  for (let i = 0; i < h; i++) world.setBlock(x, y + i, z, logId, 0, { noUpdate: true });
  const top = y + h - 1;
  if (woodType === 'spruce') {
    let r = 2;
    for (let yy = y + 2; yy <= top; yy += 2) {
      for (let dx = -r; dx <= r; dx++) for (let dz = -r; dz <= r; dz++) {
        if (Math.abs(dx) + Math.abs(dz) <= r + 1 && !(dx === 0 && dz === 0)) {
          if (world.getBlock(x + dx, yy, z + dz) === 0) world.setBlock(x + dx, yy, z + dz, leafId, 1, { noUpdate: true });
        }
      }
      r = r === 2 ? 1 : 2;
    }
    world.setBlock(x, top + 1, z, leafId, 1, { noUpdate: true });
  } else {
    for (let dy = -2; dy <= 0; dy++) {
      const r = dy === 0 ? 1 : 2;
      for (let dx = -r; dx <= r; dx++) for (let dz = -r; dz <= r; dz++) {
        if (Math.abs(dx) === r && Math.abs(dz) === r && chance(.5)) continue;
        if (!(dx === 0 && dz === 0 && dy < 0) && world.getBlock(x + dx, top + dy, z + dz) === 0)
          world.setBlock(x + dx, top + dy, z + dz, leafId, 1, { noUpdate: true });
      }
    }
    world.setBlock(x, top + 1, z, leafId, 1, { noUpdate: true });
    if (chance(.5)) { world.setBlock(x + 1, top + 1, z, leafId, 1, { noUpdate: true }); world.setBlock(x, top + 1, z + 1, leafId, 1, { noUpdate: true }); }
  }
}

// ---------- Nether portal ----------
function tryIgnitePortal(world, x, y, z) {
  // find rectangle of air enclosed by obsidian, then fill it with portal blocks
  const validate = (dx, dz) => {
    // scan width along (dx,dz)
    let minX = 0, maxX = 0;
    while (isValidPortalSpot(world, x + (minX - 1) * dx, y, z + (minX - 1) * dz)) minX--;
    while (isValidPortalSpot(world, x + (maxX + 1) * dx, y, z + (maxX + 1) * dz)) maxX++;
    const w = maxX - minX + 1;
    if (w < 2 || w > 21) return null;
    // scan height
    let minY = y, maxY = y;
    let ok = true;
    for (let ix = minX; ix <= maxX; ix++) {
      const px = x + ix * dx, pz = z + ix * dz;
      let yy = y;
      while (isValidPortalSpot(world, px, yy - 1, pz)) yy--;
      if (ix === minX) minY = yy; else if (yy !== minY) { ok = false; break; }
      let y2 = y;
      while (isValidPortalSpot(world, px, y2 + 1, pz)) y2++;
      if (ix === minX) maxY = y2; else if (y2 !== maxY) { ok = false; break; }
    }
    if (!ok) return null;
    const h = maxY - minY + 1;
    if (h < 3 || h > 21) return null;
    // frame check
    for (let ix = minX; ix <= maxX; ix++) {
      if (world.getBlock(x + ix * dx, minY - 1, z + ix * dz) !== B.obsidian) return null;
      if (world.getBlock(x + ix * dx, maxY + 1, z + ix * dz) !== B.obsidian) return null;
    }
    for (let iy = minY; iy <= maxY; iy++) {
      if (world.getBlock(x + (minX - 1) * dx, iy, z + (minX - 1) * dz) !== B.obsidian) return null;
      if (world.getBlock(x + (maxX + 1) * dx, iy, z + (maxX + 1) * dz) !== B.obsidian) return null;
    }
    return { minX, maxX, minY, maxY, dx, dz };
  };
  const horiz = validate(1, 0) || validate(0, 1);
  if (!horiz) return false;
  const { minX, maxX, minY, maxY, dx, dz } = horiz;
  const axis = dx === 1 ? 0 : 1;
  for (let ix = minX; ix <= maxX; ix++) for (let iy = minY; iy <= maxY; iy++) {
    world.setBlock(x + ix * dx, iy, z + ix * dz, B.nether_portal, axis, { noUpdate: true });
  }
  SFX.playPortalTrigger();
  return true;
}
function isValidPortalSpot(world, x, y, z) {
  const id = world.getBlock(x, y, z);
  return id === 0 || id === B.fire || id === B.nether_portal;
}

// ---------- Wither boss ritual: skull on soul sand T ----------
function trySpawnWither(world, x, y, z) {
  // clicked block must be the TOP-CENTER soul sand of a T:
  // row of 3 soul sand at y (x-1..x+1 or z-1..z+1) + center below at y-1
  const isSoul = (sx, sy, sz) => world.getBlock(sx, sy, sz) === B.soul_sand;
  const axisOK = (isSoul(x - 1, y, z) && isSoul(x + 1, y, z)) || (isSoul(x, y, z - 1) && isSoul(x, y, z + 1));
  if (!axisOK || !isSoul(x, y - 1, z)) return false;
  const p = G.player;
  if (!p || p.countItem('wither_skull_item') < 2) { Chat.actionBar('The Wither needs 3 skulls!'); return false; }
  p.consumeItem('wither_skull_item', 1);
  p.consumeItem('wither_skull_item', 1);
  spawnEntity('wither', x + .5, y + 1, z + .5);
  Chat.add('§dThe Wither has been awakened!');
  SFX.playExplosion();
  spawnParticles(x + .5, y + 1.5, z + .5, 60, [.2, .2, .2], true);
  return true;
}

// ---------- End portal frame ----------
function WinDragonFight() {
  // called when dragon dies
  UI.updateBossBar(null);
  $('win-screen').classList.add('active');
  G.state = 'dead';
  setTimeout(() => {
    $('win-screen').classList.remove('active');
    G.state = 'playing';
    requestPointerLock();
  }, 6000);
  // place exit portal at (0, y, 0)
  const world = G.world;
  if (G.dimension === 2) {
    for (let dx = -2; dx <= 2; dx++) for (let dz = -2; dz <= 2; dz++) {
      if (Math.abs(dx) === 2 || Math.abs(dz) === 2 || (dx === 0 && dz === 0)) {
        const y = 70;
        world.setBlock(dx, y, dz, B.bedrock, 0, { noUpdate: true });
        if (Math.abs(dx) < 2 && Math.abs(dz) < 2 && !(dx === 0 && dz === 0)) world.setBlock(dx, y + 1, dz, B.end_portal, 0, { noUpdate: true });
      }
    }
    world.setBlock(0, 71, 0, B.dragon_egg, 0, { noUpdate: true });
  }
}

// ============================================================================
// Part 12: Multiplayer — BroadcastChannel (same browser), WebRTC P2P,
// WebSocket relay (internet code-join via our own relay server).
// ============================================================================
// Internet relay endpoint (our own Render Web Service; override via
// localStorage 'wc_signal_url' for self-hosting/testing). Empty string
// disables the internet path entirely.
const SIGNAL_URL = (function () {
  try { return localStorage.getItem('wc_signal_url') || 'wss://webcraft-qkwp.onrender.com'; } catch (e) { return ''; }
})();
const Chat = {
  history: [],
  add(text, color) {
    const hist = $('chat-history');
    const el = mkEl('div', 'chat-msg', hist);
    if (color) el.style.color = color;
    // basic MC color code support: §a green etc.
    el.innerHTML = '';
    let buf = '', curColor = color || '';
    for (let i = 0; i < text.length; i++) {
      if (text[i] === '§' && i + 1 < text.length) {
        if (buf) { const s = mkEl('span', '', el, buf); if (curColor) s.style.color = curColor; buf = ''; }
        const code = text[++i];
        const map = { a: '#55FF55', b: '#55FFFF', c: '#FF5555', d: '#FF55FF', e: '#FFFF55', f: '#FFFFFF', 7: '#AAAAAA', 8: '#555555', 6: '#FFAA00', '9': '#5555FF', '1': '#0000AA' };
        curColor = map[code] || curColor;
      } else buf += text[i];
    }
    if (buf) { const s = mkEl('span', '', el, buf); if (curColor) s.style.color = curColor; }
    this.history.push(text);
    if (this.history.length > 100) this.history.shift();
    while (hist.children.length > 14) hist.removeChild(hist.firstChild);
    hist.scrollTop = hist.scrollHeight;
    // reveal chat briefly
    $('chat-container').classList.remove('hidden-chat');
    clearTimeout(this._hideT);
    this._hideT = setTimeout(() => { if (!$('chat-input-wrap').style.display.includes('flex')) $('chat-container').classList.add('hidden-chat'); }, 8000);
  },
  actionBar(text) {
    const el = $('action-bar-msg');
    el.textContent = text;
    el.style.opacity = '1';
    clearTimeout(this._abT);
    this._abT = setTimeout(() => el.style.opacity = '0', 2200);
  },
  open() {
    $('chat-container').classList.remove('hidden-chat');
    $('chat-input-wrap').style.display = 'flex';
    const inp = $('chat-input');
    inp.value = '';
    document.exitPointerLock && document.exitPointerLock();
    setTimeout(() => inp.focus(), 0);
  },
  close() {
    $('chat-input-wrap').style.display = 'none';
    $('chat-input').blur();
    requestPointerLock();
  },
  submit() {
    const inp = $('chat-input');
    const text = inp.value.trim();
    this.close();
    if (!text) return;
    if (text[0] === '/') Commands.run(text);
    else {
      const name = (G.net && G.net.myName) || 'Player';
      const msg = '<' + name + '> ' + text;
      Chat.add(msg);
      if (G.net) G.net.sendAll({ t: 'chat', msg });
    }
  },
};

const COMMANDS_HELP = [
  '/help — list commands',
  '/gamemode <survival|creative|spectator> — switch mode',
  '/difficulty <peaceful|easy|normal|hard> — set difficulty',
  '/time set <day|night|noon|midnight|N> — set world time',
  '/tp <x> <y> <z> — teleport',
  '/give <item> [count] — give item',
  '/seed — show world seed',
  '/weather <clear|rain|thunder> — change weather',
  '/summon <mob> [x y z] — spawn entity',
  '/kill — kill yourself',
  '/clear — clear inventory',
  '/spawnpoint — set respawn here',
  '/xp <n> — add experience',
  '/say <msg> — broadcast a message',
  '/dimension <overworld|nether|end> — travel',
  '/save — save the world now',
];

const Commands = {
  run(line) {
    const parts = line.slice(1).split(/\s+/);
    const cmd = parts[0].toLowerCase();
    const p = G.player;
    const requireHost = () => {
      if (G.net && !G.net.isHostOrSingle) { Chat.add('§cOnly the host can use this command.'); return false; }
      return true;
    };
    switch (cmd) {
      case 'help': COMMANDS_HELP.forEach(h => Chat.add('§7' + h)); break;
      case 'gamemode': {
        const gm = parts[1];
        if (!['survival', 'creative', 'spectator', 'hardcore'].includes(gm)) { Chat.add('§cUsage: /gamemode <survival|creative|spectator>'); break; }
        p.gameMode = gm;
        p.flying = gm === 'creative' || gm === 'spectator';
        Chat.add('Game mode set to ' + gm);
        break;
      }
      case 'difficulty': {
        const df = parts[1];
        if (!['peaceful', 'easy', 'normal', 'hard'].includes(df)) { Chat.add('§cUsage: /difficulty <peaceful|easy|normal|hard>'); break; }
        G.difficulty = df;
        Chat.add('§7Schwierigkeit: §f' + df);
        // host authority: guests adopt the new difficulty at once
        if (G.net && G.net.mode !== null) G.net.sendAll({ t: 'difficulty', d: df });
        break;
      }
      case 'time': {
        if (parts[1] === 'set') {
          const map = { day: 1000, noon: 6000, night: 13000, midnight: 18000 };
          const t = map[parts[2]] !== undefined ? map[parts[2]] : parseInt(parts[2]);
          if (isNaN(t)) { Chat.add('§cUsage: /time set <day|night|noon|midnight|ticks>'); break; }
          G.world.time = t;
          if (G.net && G.net.isHostOrSingle) G.net.broadcastTime();
          Chat.add('Time set to ' + t);
        }
        break;
      }
      case 'tp': {
        const [x, y, z] = [parseFloat(parts[1]), parseFloat(parts[2]), parseFloat(parts[3])];
        if (isNaN(x) || isNaN(y) || isNaN(z)) { Chat.add('§cUsage: /tp <x> <y> <z>'); break; }
        TeleportPlayer(x, y, z);
        Chat.add(`Teleported to ${x} ${y} ${z}`);
        break;
      }
      case 'give': {
        const key = parts[1];
        if (I[key] === undefined) { Chat.add('§cUnknown item: ' + key + ' (use registry keys like iron_pickaxe)'); break; }
        const n = parseInt(parts[2]) || 1;
        p.addItem(I[key], n);
        Chat.add(`Gave ${n} × ${key}`);
        break;
      }
      case 'seed': Chat.add('Seed: ' + G.seed); break;
      case 'weather': {
        if (!requireHost()) break;
        const w = parts[1];
        if (w === 'clear') { G.rain = 0; G.thunder = 0; }
        else if (w === 'rain') { G.rain = .7; G.thunder = 0; }
        else if (w === 'thunder') { G.rain = 1; G.thunder = 1; }
        else { Chat.add('§cUsage: /weather <clear|rain|thunder>'); break; }
        Chat.add('Weather: ' + w);
        if (G.net) G.net.sendAll({ t: 'weather', rain: G.rain, thunder: G.thunder });
        break;
      }
      case 'summon': {
        const type = parts[1];
        if (!MOB_DEFS[type] || ['item', 'xp', 'arrow'].includes(type)) { Chat.add('§cUnknown mob: ' + type); break; }
        let x = p.x, y = p.y, z = p.z;
        if (parts[2] !== undefined) { x = +parts[2]; y = +parts[3]; z = +parts[4]; }
        spawnEntity(type, x, y, z);
        Chat.add('Summoned ' + type);
        break;
      }
      case 'kill': p.damage(1000, 'command'); break;
      case 'clear': p.slots.fill(null); UI.refreshHotbar(); Chat.add('Inventory cleared'); break;
      case 'spawnpoint': p.spawnPoint = [p.x, p.y, p.z]; Chat.add('Spawn point set'); break;
      case 'xp': { const n = parseInt(parts[1]) || 0; p.addXP(n); Chat.add('Added ' + n + ' XP'); break; }
      case 'say': Chat.add('§e[Server] ' + parts.slice(1).join(' ')); break;
      case 'dimension': {
        const map = { overworld: 0, nether: 1, end: 2 };
        const d = map[parts[1]];
        if (d === undefined) { Chat.add('§cUsage: /dimension <overworld|nether|end>'); break; }
        TeleportDimension(d, p.x, p.z);
        break;
      }
      case 'save': SaveSystem.save(); Chat.add('World saved'); break;
      default: Chat.add('§cUnknown command. Try /help');
    }
  },
};

// ============================================================================
// Net — transport-agnostic host/peer mesh
// ============================================================================
class Net {
  constructor() {
    this.mode = null;            // 'single' | 'bc-host' | 'bc-join' | 'rtc-host' | 'rtc-join' | 'ws'
    this.isHostOrSingle = true;
    this.myName = 'Player' + randInt(100, 999);
    this.myId = 'p' + Math.random().toString(36).slice(2, 9);
    this.peers = new Map();      // id -> {send(fn), name, entity, lastSeen, pos info}
    this.bc = null;
    this.dc = null;              // WebRTC datachannel (single peer P2P)
    this.ws = null;
    this.hostId = null;
    this.snapshotT = 0;
    this.posT = 0;
  }

  log(msg, err) {
    const el = $('net-log');
    if (el) { const d = mkEl('div', err ? 'err' : '', el, msg); el.scrollTop = el.scrollHeight; }
    console.log('[net]', msg);
  }

  // ---------- transport: send to all connected peers ----------
  sendAll(obj) {
    this._midSeq = (this._midSeq || 0) + 1;
    obj._mid = this._midSeq; // dedup id — a dual-transport (BC + WS) client receives every frame twice
    const s = JSON.stringify(obj);
    this.bytesOut = (this.bytesOut || 0) + s.length; // F3 traffic meter
    if (this.bc) this.bc.postMessage({ ...obj, _from: this.myId });
    if (this.dc && this.dc.readyState === 'open') { try { this.dc.send(s); } catch (e) { } }
    if (this.ws && this.ws.readyState === 1) { try { this.ws.send(s); } catch (e) { } }
    for (const [, p] of this.peers) { if (p.send) { try { p.send(s); } catch (e) { } } }
  }

  broadcastBlock(x, y, z, id, m) {
    if (!this || this.mode === null) return;
    this.sendAll({ t: 'block', d: G.dimension, x, y, z, id, m });
  }
  broadcastTime() { this.sendAll({ t: 'time', time: G.world.time, dim: G.dimension }); }

  // ---------- receive dispatcher ----------
  onMessage(obj, reply) {
    if (obj._from === this.myId) return;
    // dedup for dual-transport clients (BC + relay deliver the same frame twice)
    if (obj._mid) {
      this._seen = this._seen || new Map();
      if (this._seen.has(obj._mid)) return;
      this._seen.set(obj._mid, performance.now());
      if (this._seen.size > 400) { const it = this._seen.keys(); for (let i = 0; i < 200; i++) this._seen.delete(it.next().value); }
    }
    switch (obj.t) {
      case 'host-here': {
        // discovery announce (BroadcastChannel)
        if (this.mode === 'bc-join' && !this.joined) {
          this.hostId = obj.id;
          reply({ t: 'join', id: this.myId, name: this.myName });
          this.log('Found host — joining...');
        }
        break;
      }
      case 'join': {
        if (!this.isHostOrSingle) break;
        if (this.peers.has(obj.id)) break; // join retries must not spam the chat
        this.peers.set(obj.id, { name: obj.name, send: reply ? (s) => reply(JSON.parse(s) ? s : s) : null, lastSeen: performance.now(), bcReply: reply });
        // send welcome with full state
        const welcome = {
          t: 'welcome', to: obj.id, id: this.myId, name: this.myName,
          seed: G.seed, time: G.world.time, mode: G.gameMode, difficulty: G.difficulty || 'normal',
          edits: [...G.world.edits.entries()],
          tes: this.serializeTEs(),
          rain: G.rain, thunder: G.thunder,
        };
        if (reply) reply(welcome);
        Chat.add('§e' + obj.name + ' hat das Spiel betreten');
        // create remote player entity
        this.ensureRemotePlayer(obj.id, obj.name);
        break;
      }
      case 'welcome': {
        if (obj.to !== this.myId && obj.to !== undefined) { /* broadcast welcome to all — ignore others */ }
        this.hostId = obj.id;
        this.isHostOrSingle = false;
        this.joined = true;
        // build (or rebuild) the world deterministically from the host's data —
        // a guest can join straight from the title screen, no local world needed.
        // Same seed + already playing → keep the local world, only adopt state.
        if (!G.world || (G.seed >>> 0) !== (obj.seed >>> 0)) {
          joinWorldFromHost(obj);
        } else {
          G.world.edits = new Map(obj.edits);
          // apply the host's edits into the generated chunks (setBlock handles
          // heightmap, light and remesh; noEdit — the map already has them)
          for (const [k, v] of G.world.edits) {
            const [ex, ey, ez] = k.split(',').map(Number);
            G.world.setBlock(ex, ey, ez, v[0], v[1], { noEdit: true, noNet: true });
          }
          G.world.time = obj.time;
          G.rain = obj.rain; G.thunder = obj.thunder;
          G.gameMode = obj.mode || G.gameMode;
          if (G.player) G.player.gameMode = G.gameMode;
          if (obj.difficulty) G.difficulty = obj.difficulty;
          // same world already here (quit to title earlier) → drop back into
          // the game, otherwise the guest stays stuck on the title screen
          if (G.state === 'title') {
            showScreen(null);
            G.state = 'playing';
            if (G.player) G.player.spawnGrace = 100;
            UI.refreshHotbar();
            requestPointerLock();
          }
        }
        this.deserializeTEs(obj.tes);
        // guests see the code in the ESC menu too (badge value only; showScreen toggles visibility)
        const val = document.getElementById('mp-code-value');
        if (val) val.textContent = this.roomCode;
        this.log('Connected! World seed: ' + obj.seed);
        Chat.add('§aConnected to ' + obj.name + "'s world");
        Chat.add('§7Modus: §f' + (G.gameMode || 'survival') + ' §7· Schwierigkeit: §f' + (G.difficulty || 'normal'));
        break;
      }
      case 'pos': {
        if (obj.id === this.myId) break;
        const ent = this.ensureRemotePlayer(obj.id, obj.name);
        if (ent) {
          ent.dead = !!obj.d; // MC: the remote model tips over when the player dies
          if (!ent.dead) ent.deathTime = 0;
          // MC-style snapshot interpolation: keep the last two received
          // positions and slide between them at a fixed delay. A per-tick
          // lerp toward the target instead leaves an exponential tail (the
          // avatar "ice-skates" after the sender stopped) and steps at 10 Hz.
          ent.sx = ent.tx !== undefined ? ent.tx : obj.x;
          ent.sy = ent.ty !== undefined ? ent.ty : obj.y;
          ent.sz = ent.tz !== undefined ? ent.tz : obj.z;
          ent.tx = obj.x; ent.ty = obj.y; ent.tz = obj.z;
          ent.snapT = performance.now();
          // yaw along the shortest arc between snapshots
          ent.syaw = ent.tyaw !== undefined ? ent.tyaw : obj.yaw;
          ent.tyaw = obj.yaw;
          ent.tpitch = obj.pitch;
          ent.walkSpeed = obj.sp || 0;
          ent.swingT2 = obj.sw ? 10 : (ent.swingT2 || 0);
          ent.lastSeen = performance.now(); // stale watchdog reference
          if (ent.swingT2 > 0) ent.swingT2--;
        }
        const peer = this.peers.get(obj.id) || this.bcPeers?.get(obj.id);
        break;
      }
      case 'block': {
        // cooperative model: remote edits are always applied (the sender's
        // own world already has them; the host is not an authority filter)
        applyRemoteBlock(obj);
        break;
      }
      case 'chat': Chat.add(obj.msg); break;
      // the host's clock wins (host authority); a guest's local /time set is
      // overridden at the next 5s sync
      case 'time': if (!this.isHostOrSingle) G.world.time = obj.time; break;
      // difficulty changes from the host apply instantly (peaceful despawns etc.)
      case 'difficulty':
        if (!this.isHostOrSingle && ['peaceful', 'easy', 'normal', 'hard'].includes(obj.d)) {
          G.difficulty = obj.d;
          Chat.add('§7Schwierigkeit: §f' + obj.d);
        }
        break;
      case 'weather': G.rain = obj.rain; G.thunder = obj.thunder; break;
      case 'te': this.applyTE(obj.k, obj.te); break;
      case 'left': {
        const e = this.remotePlayers?.get(obj.id);
        if (e) {
          e.dead = true;
          const i = G.entities.indexOf(e);
          if (i >= 0) G.entities.splice(i, 1); // fully despawn — a dead corpse must not linger
          this.remotePlayers.delete(obj.id);
        }
        this.peers.delete(obj.id);
        Chat.add('§e' + (obj.name || 'Ein Spieler') + ' hat das Spiel verlassen');
        break;
      }
    }
  }

  serializeTEs() {
    const out = [];
    for (const [k, te] of G.tileEntities) {
      const [d] = [0];
      out.push([k, te]);
    }
    return out;
  }
  deserializeTEs(arr) {
    for (const [k, te] of arr) G.tileEntities.set(k, te);
  }
  applyTE(k, te) {
    G.tileEntities.set(k, te);
    // remesh chunk
    const [x, y, z] = k.split(',').map(Number);
    const c = G.world.getChunk(x >> 4, z >> 4);
    if (c) c.dirty = true;
  }

  ensureRemotePlayer(id, name) {
    this.remotePlayers = this.remotePlayers || new Map();
    let e = this.remotePlayers.get(id);
    if (!e) {
      // a stale fallen model must never linger as a ghost in G.entities
      if (e) { const i = G.entities.indexOf(e); if (i >= 0) G.entities.splice(i, 1); }
      const def = Object.assign({}, MOB_DEFS.player_remote, { model: 'humanoid' });
      e = new Entity('player_remote', G.player.x, G.player.y, G.player.z, def, {});
      e.nameTag = name;
      e.remoteId = id;
      e.hittable = false;
      e.isRemotePlayer = true;
      e.noAI = true; // position/animation come purely from snapshots — local mob AI would fight them
      e.tx = e.x; e.ty = e.y; e.tz = e.z;
      G.entities.push(e);
      this.remotePlayers.set(id, e);
    }
    return e;
  }

  // ---------- BroadcastChannel mode ----------
  startBC(host, code) {
    this.mode = host ? 'bc-host' : 'bc-join';
    this.isHostOrSingle = host;
    // room code: host generates a 6-char code, guests join by entering it
    if (host && !this.roomCode) {
      const chars = 'ABCDEFGHJKLMNPQRSTUVWXYZ23456789';
      this.roomCode = '';
      for (let i = 0; i < 6; i++) this.roomCode += chars[Math.floor(Math.random() * chars.length)];
    } else if (code) this.roomCode = code.toUpperCase().replace(/[^A-Z0-9]/g, '').slice(0, 6);
    if (!this.roomCode || this.roomCode.length < 4) {
      // guest without a code: listen on the shared LAN discovery channel and
      // hop onto whatever host announces itself there ("join same browser")
      if (!host) { this._discoveryJoin = true; this.roomCode = 'LAN'; }
      else this.roomCode = 'DEFAULT';
    }
    this.bc = new BroadcastChannel('webcraft-' + this.roomCode);
    this._bindChannel();
    if (host) {
      // announce on the private room channel AND the shared discovery channel;
      // also ANSWER discovery requests immediately (guest does not wait 1.5 s)
      this._disco = new BroadcastChannel('webcraft-LAN');
      this._disco.onmessage = (ev) => {
        const obj = ev.data;
        if (obj && obj.t === 'discover') {
          try { this._disco.postMessage({ t: 'host-here', id: this.myId, name: this.myName, ch: this.roomCode, playing: G.state === 'playing' }); } catch (e) { }
        }
      };
      this._announce = setInterval(() => {
        try {
          const m = { t: 'host-here', id: this.myId, name: this.myName, ch: this.roomCode, playing: G.state === 'playing' };
          this.bc.postMessage(m);
          this._disco.postMessage(m);
        } catch (e) { }
      }, 1500);
      this.log('Hosting on BroadcastChannel (open the page in another tab to join)');
      // the HUD badge is ONLY shown inside menu overlays (showScreen) — never during gameplay
      const val = document.getElementById('mp-code-value');
      if (val) val.textContent = this.roomCode;
      Chat.add('§aMultiplayer-Code: §f' + this.roomCode + ' §7— sichtbar im ESC-Menü');
    } else {
      this.log('Suche nach Host im selben Browser...');
      // instant discovery request instead of waiting for the next announce tick
      if (this._discoveryJoin) {
        setTimeout(() => { try { this.bc.postMessage({ t: 'discover', id: this.myId }); } catch (e) { } }, 120);
      } else {
        // coded join: request membership directly and retry every 1.5 s until
        // the host answers (no dependence on announce timing)
        this.sendAll({ t: 'join', id: this.myId, name: this.myName });
        this._joinRetry = setInterval(() => {
          if (this.joined || this.mode === null) { clearInterval(this._joinRetry); return; }
          this.sendAll({ t: 'join', id: this.myId, name: this.myName });
        }, 1500);
      }
      setTimeout(() => { if (!this.joined) this.log('Noch kein Host gefunden — Host-Tab geöffnet und Code korrekt?', true); }, 4000);
      // guest stuck on the search screen: send them back with a clear message
      setTimeout(() => {
        if (!this.joined && G.state === 'title') {
          showScreen('multiplayer-screen');
          Chat.add('§cKein Host gefunden — läuft das Host-Spiel im selben Browser, oder stimmt der Code?');
        }
      }, 8000);
    }
  }

  // channel message binding — re-runnable so a discovery guest can hop onto
  // the host's private room channel without losing the handler
  _bindChannel() {
    this.bc.onmessage = (ev) => {
      const obj = ev.data;
      const reply = (o) => { try { this.bc.postMessage({ ...o, _to: obj.id }); } catch (e) { } };
      if (obj._to && obj._to !== this.myId && obj.t !== 'welcome') return;
      // discovery guest: a host announced itself — hop onto his private room
      // channel and start the join handshake. Prefer hosts that are IN-GAME
      // (obj.playing); a host that already announced but never answers (stale
      // tab) is retried once, then the guest returns to the discovery channel.
      if (this._discoveryJoin && obj.t === 'host-here' && obj.ch && obj.ch !== this.roomCode) {
        if (this._triedHosts && this._triedHosts.has(obj.ch) && !obj.playing) return;
        this._triedHosts = this._triedHosts || new Set();
        this._discoveryJoin = false;
        try { this.bc.close(); } catch (e) { }
        this.roomCode = obj.ch;
        try { this.bc = new BroadcastChannel('webcraft-' + this.roomCode); } catch (e) { return; }
        this._bindChannel();
        this._triedHosts.add(this.roomCode);
        this.log('Host gefunden (' + this.roomCode + ') — Beitritt...');
        this.sendAll({ t: 'join', id: this.myId, name: this.myName });
        // fallback: no welcome within 2.5 s → this announce was stale; go back
        // to the discovery channel and keep searching
        setTimeout(() => {
          if (!this.joined && G.net === this && this.mode === 'bc-join') {
            this.log('Host antwortet nicht — Suche läuft weiter...');
            try { this.bc.close(); } catch (e) { }
            this.roomCode = 'LAN';
            this.bc = new BroadcastChannel('webcraft-LAN');
            this._bindChannel();
            this._discoveryJoin = true;
            setTimeout(() => { try { this.bc.postMessage({ t: 'discover', id: this.myId }); } catch (e) { } }, 120);
          }
        }, 2500);
        return;
      }
      this.onMessage(obj, reply);
    };
  }

  // ---------- WebRTC manual mode ----------
  async startRTC(host) {
    this.mode = host ? 'rtc-host' : 'rtc-join';
    this.isHostOrSingle = host;
    this.rtcPC = new RTCPeerConnection({
      // public STUN in the documented MDN RTCIceServer `urls` syntax (Google's
      // servers follow the webrtc.org samples convention). Host candidates
      // alone suffice inside one LAN; STUN covers most home-NAT topologies.
      // A TURN relay is the documented remedy for symmetric NATs (none free).
      iceServers: [{ urls: ['stun:stun.l.google.com:19302', 'stun:stun1.l.google.com:19302'] }],
    });
    const area = $('sdp-area');
    this.rtcPC.ondatachannel = (ev) => this.setupDC(ev.channel);
    if (host) {
      this.dc = this.rtcPC.createDataChannel('game', { ordered: true });
      this.setupDC(this.dc);
      const offer = await this.rtcPC.createOffer();
      await this.rtcPC.setLocalDescription(offer);
      this.log('Creating invite code (gather ICE candidates)...');
      await this.waitForIce(this.rtcPC);
      area.value = btoa(JSON.stringify(this.rtcPC.localDescription));
      this.log('Invite code ready — copy it to your friend.');
    }
  }
  async rtcJoinWithCode(code) {
    const desc = JSON.parse(atob(code.trim()));
    await this.rtcPC.setRemoteDescription(desc);
    const answer = await this.rtcPC.createAnswer();
    await this.rtcPC.setLocalDescription(answer);
    await this.waitForIce(this.rtcPC);
    $('sdp-area').value = btoa(JSON.stringify(this.rtcPC.localDescription));
    this.log('Answer code generated — send it back to the host and let them press Apply.');
  }
  async rtcHostApplyCode(code) {
    const desc = JSON.parse(atob(code.trim()));
    await this.rtcPC.setRemoteDescription(desc);
    this.log('Connected! Applying world...');
    // send join+welcome
    setTimeout(() => {
      this.peers.set('rtc', { name: 'Friend', send: null, lastSeen: performance.now() });
      this.sendAll({ t: 'welcome', to: 'rtc', id: this.myId, name: this.myName, seed: G.seed, time: G.world.time, mode: G.gameMode, edits: [...G.world.edits.entries()], tes: this.serializeTEs(), rain: G.rain, thunder: G.thunder });
    }, 500);
  }
  waitForIce(pc) {
    return new Promise((resolve) => {
      if (pc.iceGatheringState === 'complete') return resolve();
      const check = () => { if (pc.iceGatheringState === 'complete') { cleanup(); resolve(); } };
      const cleanup = () => { clearInterval(t); pc.removeEventListener('icegatheringstatechange', check); };
      const t = setInterval(check, 200);
      pc.addEventListener('icegatheringstatechange', check);
      setTimeout(() => { cleanup(); resolve(); }, 4000); // don't wait forever
    });
  }
  setupDC(dc) {
    this.dc = dc;
    dc.onmessage = (ev) => {
      try { this.onMessage(JSON.parse(ev.data)); } catch (e) { }
    };
    dc.onopen = () => this.log('DataChannel open — connected!');
    dc.onclose = () => this.log('DataChannel closed', true);
  }

  // ---------- WebSocket relay ----------
  connectWS(url) {
    try {
      this.ws = new WebSocket(url);
      if (!this.bc) { this.mode = 'ws'; this.isHostOrSingle = !this._wsJoinedAsClient; }
      this.ws.onopen = () => {
        this.log('Relay verbunden (Internet-Modus, Raum: ' + (this.roomCode || 'default') + ').');
        this.ws.send(JSON.stringify({ t: 'join-room', room: 'webcraft-' + (this.roomCode || 'default'), id: this.myId }));
        // hardening: OUR relay confirms with room-joined — anything else is a
        // foreign service on that URL (wrong Render service name)
        setTimeout(() => {
          if (this.ws && this.ws.readyState === 1 && !this._roomJoined) {
            this.log('§cRelay-Antwort unerwartet — das ist NICHT unser Relay-Server. Render-Service-Name/URL prüfen!', true);
          }
        }, 3000);
        // coded join over the relay: request membership immediately (no wait)
        if (!this.isHostOrSingle) this.sendAll({ t: 'join', id: this.myId, name: this.myName });
      };
      this.ws.onmessage = (ev) => {
        try {
          const obj = JSON.parse(ev.data);
          if (obj.t === 'room-joined') { this._roomJoined = true; this.log('Relay-Raum betreten — wartet auf Spieler...'); return; }
          this.onMessage(obj, (o) => { try { this.ws.send(JSON.stringify({ ...o, _to: obj.id })); } catch (e) { } });
        } catch (e) { }
      };
      this.ws.onclose = () => this.log('Relay disconnected', true);
      this.ws.onerror = () => this.log('Relay error — check the URL', true);
    } catch (e) { this.log('WS error: ' + e.message, true); }
  }

  // ---------- per-tick sync ----------
  tick() {
    if (this.mode === null) return;
    // periodic time sync — the host is the clock authority. Without this the
    // tabs' day/night cycles drift apart within minutes (measured: 8 min apart)
    this.timeT = (this.timeT || 0) + 1;
    if (this.timeT >= 100) { // every 5s at 20 TPS
      this.timeT = 0;
      if (this.isHostOrSingle) this.sendAll({ t: 'time', time: G.world.time, dim: G.dimension });
    }
    this.posT--;
    // also send from the multiplayer menu — the world (and gravity) keeps
    // running there, so the remote side must keep seeing us move
    if (this.posT <= 0 && G.player && (G.state === 'playing' || G.state === 'paused' || G.state === 'dead')) {
      this.posT = 1; // 20 Hz — Minecraft sends 20 positions/s
      const p = G.player;
      this.sendAll({
        t: 'pos', id: this.myId, name: this.myName,
        x: +p.x.toFixed(2), y: +p.y.toFixed(2), z: +p.z.toFixed(2),
        yaw: +p.yaw.toFixed(2), pitch: +p.pitch.toFixed(2),
        sp: +Math.hypot(p.vx, p.vz).toFixed(2), sw: p.swingT > .5,
        d: p.dead ? 1 : 0, // MC: the remote model tips over when you die
      });
    }
    // interpolate remote players — MC-style snapshots: slide at constant speed
    // between the last two received positions (20 Hz → 50 ms delay). The old
    // per-tick lerp(0.25) left an exponential tail (avatar "ice-skates" on
    // after the sender stopped) and visibly stepped at 10 Hz.
    if (this.remotePlayers) {
      const nowMs = performance.now();
      for (const [rid, e] of this.remotePlayers) {
        // stale watchdog: a page that closed without delivering its 'left'
        // message (unload quirk) despawns after 5 s of silence
        if (!e.dead && e.lastSeen && nowMs - e.lastSeen > 5000) {
          e.dead = true;
          const i = G.entities.indexOf(e);
          if (i >= 0) G.entities.splice(i, 1);
          this.remotePlayers.delete(rid);
          this.peers.delete(rid);
          Chat.add('§e' + (e.nameTag || 'Ein Spieler') + ' hat das Spiel verlassen');
          continue;
        }
        if (e.dead) { e.deathTime++; continue; } // tip the fallen model over
        const a = Math.min(1, (nowMs - (e.snapT || nowMs)) / 50); // 50 ms = one 20 Hz snapshot interval
        const sx = e.sx ?? e.tx ?? e.x, sy = e.sy ?? e.ty ?? e.y, sz = e.sz ?? e.tz ?? e.z;
        e.x = sx + ((e.tx ?? sx) - sx) * a;
        e.y = sy + ((e.ty ?? sy) - sy) * a;
        e.z = sz + ((e.tz ?? sz) - sz) * a;
        // yaw along the shortest arc
        e.yawO = e.yaw; // for emitPart's interpolated body yaw (keep BEFORE reassigning)
        let dyaw = (e.tyaw ?? e.yaw) - (e.syaw ?? e.yaw);
        while (dyaw > Math.PI) dyaw -= Math.PI * 2;
        while (dyaw < -Math.PI) dyaw += Math.PI * 2;
        e.yaw = (e.syaw ?? e.yaw) + dyaw * a;
        e.pitch = e.tpitch ?? e.pitch;
        // animation phase: previous values kept for the render-alpha interpolation.
        // The phase constant MUST match local mobs (walkSpeed is in ticks-velocity
        // units ≈ 0.2 while walking; the old ×22 cycled the legs ~13 rad/s = shaking)
        e.walkAnimO = e.walkAnim;
        e.walkSpeedO = e.walkSpeed;
        e.walkAnim += (e.walkSpeed || 0) * 3.2;
      }
    }
  }

  shutdown() {
    const badge = document.getElementById('mp-code-badge');
    if (badge) badge.style.display = 'none';
    this.sendAll({ t: 'left', id: this.myId, name: this.myName });
    clearInterval(this._announce);
    clearInterval(this._joinRetry);
    try { this._disco && this._disco.close(); } catch (e) { }
    try { this.bc && this.bc.close(); } catch (e) { }
    try { this.dc && this.dc.close(); } catch (e) { }
    try { this.ws && this.ws.close(); } catch (e) { }
    this.mode = null;
    this.peers.clear();
  }
}

function applyRemoteBlock(obj) {
  // world not built yet (guest is still joining) → queue; drained after the
  // welcome rebuild (see startGame's mesh completion)
  if (!G.world) { G.pendingRemoteEdits = G.pendingRemoteEdits || []; G.pendingRemoteEdits.push(obj); return; }
  // blocks for OTHER dimensions: apply to the cached dimension world, or park
  // them in its edit list so nothing is lost when the player travels there
  if (obj.d !== G.dimension) {
    const dw = (typeof DIM_WORLDS !== 'undefined') && DIM_WORLDS.get(obj.d);
    if (dw) dw.setBlock(obj.x, obj.y, obj.z, obj.id, obj.m, { noNet: true });
    else {
      G.dimEdits = G.dimEdits || {};
      G.dimEdits[obj.d] = (G.dimEdits[obj.d] || []).concat([[obj.x + ',' + obj.y + ',' + obj.z, [obj.id, obj.m || 0]]]);
    }
    return;
  }
  // record FIRST — the edits map is the source of truth for chunk generation
  // (ensureChunk applies it); setBlock then applies into the chunk right away
  // if it exists (heightmap, light, remesh). noEdit avoids double-recording.
  G.world.edits.set(obj.x + ',' + obj.y + ',' + obj.z, [obj.id, obj.m || 0]);
  G.world.setBlock(obj.x, obj.y, obj.z, obj.id, obj.m, { noEdit: true, noNet: true });
}

// tile entity change broadcast (called on container close)
function broadcastTE(key) {
  if (G.net && G.net.mode !== null) {
    const te = G.tileEntities.get(key);
    if (te) G.net.sendAll({ t: 'te', k: key, te });
  }
}

// ============================================================================
// Part 13: Dimensions — nether/end travel, dragon fight setup
// ============================================================================
const DIM_WORLDS = new Map();  // dim -> World

function getWorldFor(dim) {
  if (dim === G.dimension) return G.world;
  let w = DIM_WORLDS.get(dim);
  if (!w) {
    w = new World(G.seed, dim);
    DIM_WORLDS.set(dim, w);
  }
  return w;
}

function TeleportPlayer(x, y, z) {
  const p = G.player;
  p.x = x; p.y = y; p.z = z;
  p.px = x; p.py = y; p.pz = z;   // no camera glide across the world
  p.isTeleporting = true;
  setTimeout(() => { p.isTeleporting = false; }, 100);
  p.vx = p.vy = p.vz = 0;
  p.fallDistance = 0;
  // ensure destination chunks are generated
  const w = G.world;
  for (let cx = Math.floor((x - 16) / CH); cx <= Math.floor((x + 16) / CH); cx++)
    for (let cz = Math.floor((z - 16) / CH); cz <= Math.floor((z + 16) / CH); cz++)
      w.ensureChunk(cx, cz);
  // find safe ground
  let sy = Math.min(WORLD_H - 3, Math.max(2, Math.floor(y)));
  const solidAt = (yy) => { const id = w.getBlock(Math.floor(x), yy, Math.floor(z)); return id > 0 && BLOCKS[id].solid; };
  while (sy < WORLD_H - 2 && !solidAt(sy)) sy++;
  if (solidAt(sy)) p.y = sy + 1.01;
}

function TeleportDimension(targetDim, fromX, fromZ) {
  const p = G.player;
  if (targetDim === G.dimension) return;
  SFX.playPortalTrigger();
  // coordinate scaling overworld <-> nether
  let tx = fromX, tz = fromZ;
  if (G.dimension === 0 && targetDim === 1) { tx = Math.floor(fromX / 8); tz = Math.floor(fromZ / 8); }
  else if (G.dimension === 1 && targetDim === 0) { tx = Math.floor(fromX * 8); tz = Math.floor(fromZ * 8); }

  const oldWorld = G.world;
  // swap world
  G.world = getWorldFor(targetDim);
  G.dimension = targetDim;

  // pre-generate around destination
  const R = 2;
  for (let cx = Math.floor((tx - R * CH) / CH); cx <= Math.floor((tx + R * CH) / CH); cx++)
    for (let cz = Math.floor((tz - R * CH) / CH); cz <= Math.floor((tz + R * CH) / CH); cz++)
      G.world.ensureChunk(cx, cz);

  // find portal spot or build one
  let px = Math.floor(tx), pz = Math.floor(tz);
  let py = -1;
  // search existing portal nearby
  outer:
  for (let r = 0; r < 24 && py < 0; r += 4) {
    for (let dx = -r; dx <= r && py < 0; dx += 4) {
      for (let dz = -r; dz <= r && py < 0; dz += 4) {
        const sx = px + dx, sz = pz + dz;
        for (let y = 1; y < WORLD_H - 3; y++) {
          if (G.world.getBlock(sx, y, sz) === B.nether_portal) { px = sx; pz = sz; py = y; break; }
        }
      }
    }
  }
  if (py < 0) {
    // build a new portal at destination
    py = findPortalY(G.world, px, pz);
    buildPortalFrame(G.world, px, py, pz);
    py = py + 1;
  }
  p.x = px + .5; p.z = pz + .5;
  p.y = py + .5;
  p.px = p.x; p.py = p.y; p.pz = p.z;
  p.isTeleporting = true;
  setTimeout(() => { p.isTeleporting = false; }, 100);
  p.vx = p.vy = p.vz = 0;
  p.fallDistance = 0;
  p.portalTime = -40; // grace period

  // clear entities (they belong to the old dimension); re-init dragon if End
  G.entities.length = 0;
  G.particles.length = 0;
  if (targetDim === 2) setupEndFight();
  if (targetDim === 0 && G._dragonDefeated) { /* portal already placed */ }
  // update sky immediately
  $('underwater-overlay').style.opacity = '0';
  Chat.add('§d' + (targetDim === 1 ? 'Entering the Nether...' : targetDim === 2 ? 'Entering the End...' : 'Returning to the Overworld...'));
}

function findPortalY(world, x, z) {
  if (G.dimension === 1) {
    // nether: find air pocket with floor
    for (let y = 34; y < 90; y++) {
      const below = world.getBlock(x, y - 1, z), at = world.getBlock(x, y, z), above = world.getBlock(x, y + 1, z), above2 = world.getBlock(x, y + 2, z), above3 = world.getBlock(x, y + 3, z);
      if (below === B.netherrack && at === 0 && above === 0 && above2 === 0 && above3 === 0) return y;
    }
    // carve a pocket
    for (let dy = 0; dy < 5; dy++) for (let dx = -2; dx <= 3; dx++) for (let dz = -2; dz <= 3; dz++) {
      world.setBlock(x + dx, 40 + dy, z + dz, 0, 0, { noUpdate: true });
    }
    return 40;
  }
  // overworld: surface
  for (let y = WORLD_H - 4; y > 1; y--) {
    const id = world.getBlock(x, y, z);
    if (id > 0 && BLOCKS[id].solid && world.getBlock(x, y + 1, z) === 0 && world.getBlock(x, y + 2, z) === 0 && world.getBlock(x, y + 3, z) === 0 && world.getBlock(x, y + 4, z) === 0) return y + 1;
  }
  return 70;
}

function buildPortalFrame(world, x, y, z) {
  // 4 wide (x), 5 tall portal facing z-axis (axis meta 1 = z-plane)
  for (let dx = -1; dx <= 2; dx++) for (let dy = -1; dy <= 4; dy++) {
    const isFrame = dx === -1 || dx === 2 || dy === -1 || dy === 4;
    world.setBlock(x + dx, y + dy, z, isFrame ? B.obsidian : 0, 0, { noUpdate: true });
  }
  for (let dx = 0; dx <= 1; dx++) for (let dy = 0; dy <= 3; dy++) {
    world.setBlock(x + dx, y + dy, z, B.nether_portal, 1, { noUpdate: true });
  }
  // platform in front/back
  for (let dx = -1; dx <= 2; dx++) for (let dz = -2; dz <= 2; dz++) {
    const below = world.getBlock(x + dx, y - 1, z + dz);
    if (below === 0) world.setBlock(x + dx, y - 1, z + dz, G.dimension === 1 ? B.netherrack : B.stone, 0, { noUpdate: true });
  }
}

// ---------- End fight ----------
function setupEndFight() {
  // ensure center island is generated
  for (let cx = -4; cx <= 4; cx++) for (let cz = -4; cz <= 4; cz++) G.world.ensureChunk(cx, cz);
  if (G._endInit) return;
  G._endInit = true;
  // crystals on the 10 pillars
  for (let p = 0; p < 10; p++) {
    const ang = p / 10 * Math.PI * 2;
    const pxw = Math.round(Math.cos(ang) * 42), pzw = Math.round(Math.sin(ang) * 42);
    const h = 78 + ((mulberry32(G.seed ^ (p * 7919))() * 18) | 0);
    const crystal = new Entity('crystal', pxw + .5, h + 1, pzw + .5, { w: 1, h: 2, health: 1, xp: 0 }, {});
    crystal.hittable = true;
    crystal.crystalHeal = true;
    G.entities.push(crystal);
  }
  // dragon
  const dragon = spawnEntity('dragon', 0, 80, 0);
  dragon.orbitR = 38; dragon.orbitY = 82;
  Chat.add('§dThe Ender Dragon awakens!');
}

